DG.put("giaan-prabodh/4",{"n":4,"title":"ਰਾਜਾ ਜਨਮੇਜਾ ਰਾਜ ਪਾਵਤ ਭਏ","title_roman":"Raajaa janmejaa raaj paavat bhae","page":269,"blocks":[{"type":"heading","kind":"chhand","name":"ਰੂਆਲ ਛੰਦ","gurmukhi":"ਰੂਆਲ ਛੰਦ","roman":"Rooaal chhand","meaning_en":"Ruaal metre.","page":269,"meaning_status":"draft"},{"type":"verse","number":[1,165],"number_text":"੧। ੧੬੫।","page":269,"lines":[{"gurmukhi":"ਰਾਜ ਕੋ ਗ੍ਰਿਹ ਪਾਇਕੈ ਜਨਮੇਜ ਰਾਜ ਮਹਾਨ।","roman":"Raaj ko grih paaikai janmej raaj mahaan |","meaning_en":"Having gained the house of the kingdom, Janmejai, the great king,","page":269,"meaning_status":"draft"},{"gurmukhi":"ਸੂਰਬੀਰ ਹਠੀ ਤਪੀ ਦਸ ਚਾਰ ਚਾਰ ਨਿਧਾਨ।","roman":"Soorbeer hathee tapee das chaar chaar nidhaan |","meaning_en":"a hero, resolute, an ascetic, a treasury of the fourteen (sciences),","page":269,"meaning_status":"draft","note":"ਦਸ ਚਾਰ ਚਾਰ ਨਿਧਾਨ: as in 3.8.3; uncertain."},{"gurmukhi":"ਪਿਤਰ ਕੇ ਬਧ ਕੋਪ ਤੇ ਸਬ ਬਿਪ੍ਰ ਲੀਨ ਬੁਲਾਇ।","roman":"Pitar ke badh kop te sab bipr leen bulaai |","meaning_en":"in anger at his father's killing called all the Brahmins,","page":269,"meaning_status":"draft"},{"gurmukhi":"ਸਰਪ ਮੇਧ ਕਰਿਯੋ ਲਗੇ ਮਖ ਧਰਮ ਕੇ ਚਿਤ ਚਾਇ। ੧। ੧੬੫।","roman":"Sarap medh kariyo lage makh dharam ke chit chaai | 1 | 165 |","meaning_en":"and began the serpent sacrifice, with heart eager for the dharma of sacrifice.","page":269,"meaning_status":"draft"}]},{"type":"verse","number":[2,166],"number_text":"੨। ੧੬੬।","page":269,"lines":[{"gurmukhi":"ਏਕ ਕੋਸ ਪ੍ਰਮਾਨ ਲਉ ਮਖ ਕੁੰਡ ਕੀਨ ਬਨਾਇ।","roman":"Ek kos pramaan lau makh kund keen banaai |","meaning_en":"He had a sacrificial fire-pit made, a kos in size;","page":269,"meaning_status":"draft"},{"gurmukhi":"ਮੰਤ੍ਰ ਸਕਤ ਕਰਨੈ ਲਗੇ ਤਹਿ ਹੋਮ ਬਿਪ੍ਰ ਬਨਾਇ।","roman":"Mantr sakat karnai lage tahi hom bipr banaai |","meaning_en":"there the Brahmins began the offerings with the power of mantras;","page":269,"meaning_status":"draft"},{"gurmukhi":"ਆਨ ਆਨ ਗਿਰੈ ਲਗੇ ਤਹਿ ਸਰਪ ਕੋਟ ਅਪਾਰ।","roman":"Aan aan girai lage tahi sarap kot apaar |","meaning_en":"countless millions of serpents began to come and fall in there;","page":269,"meaning_status":"draft"},{"gurmukhi":"ਜਤ੍ਰ ਤਤ੍ਰ ਉਠੀ ਜੈਤ ਧੁਨ ਭੂਮ ਭੂਰ ਉਦਾਰ। ੨। ੧੬੬।","roman":"Jatr tatr uthee jait dhun bhoom bhoor udaar | 2 | 166 |","meaning_en":"cries of victory rose everywhere, loud over all the earth.","page":269,"meaning_status":"draft"}]},{"type":"verse","number":[3,167],"number_text":"੩।੧੬੭।","page":270,"lines":[{"gurmukhi":"ਹਸਤ ਏਕ ਦੂ ਹਸਤ ਤੀਨ ਚਉ ਹਸਤ ਪੰਚ ਪ੍ਰਮਾਨ।","roman":"Hasat ek doo hasat teen chau hasat panch pramaan |","meaning_en":"One cubit, two cubits, three, four and five cubits long,","page":270,"meaning_status":"draft","note":"ਹਸਤ: 'cubit' (hand-length)."},{"gurmukhi":"ਬੀਸ ਹਾਥ ਇਕੀਸ ਹਾਥ ਪਚੀਸ ਹਾਥ ਸਮਾਨ।","roman":"Bees haath ikees haath pachees haath samaan |","meaning_en":"twenty cubits, twenty-one cubits, twenty-five cubits,","page":270,"meaning_status":"draft"},{"gurmukhi":"ਤੀਸ ਹਾਥ ਬਤੀਸ ਹਾਥ ਛਤੀਸ ਹਾਥ ਗਿਰਾਹਿ।","roman":"Tees haath batees haath chhatees haath giraahi |","meaning_en":"thirty cubits, thirty-two cubits, thirty-six cubits they fell;","page":270,"meaning_status":"draft"},{"gurmukhi":"ਆਨ ਆਨ ਗਿਰੈ ਤਹਾ ਸਭ ਭਸਮ ਭੂਤ ਹੋਇ ਜਾਇ। ੩।੧੬੭।","roman":"Aan aan girai tahaa sabh bhasam bhoot hoi jaai | 3 | 167 |","meaning_en":"they came and fell in there, and all were burned to ashes.","page":270,"meaning_status":"draft"}]},{"type":"verse","number":[4,168],"number_text":"੪। ੧੬੮।","page":270,"lines":[{"gurmukhi":"ਏਕ ਸੌ ਹਸਤ ਪ੍ਰਮਾਨ ਦੋ ਸੌ ਹਸਤ ਪ੍ਰਮਾਨ।","roman":"Ek sau hasat pramaan do sau hasat pramaan |","meaning_en":"A hundred cubits long, two hundred cubits long,","page":270,"meaning_status":"draft"},{"gurmukhi":"ਤੀਨ ਸੌ ਹਸਤ ਪ੍ਰਮਾਨ ਚਤ੍ਰ ਸੈ ਸੁ ਸਮਾਨ।","roman":"Teen sau hasat pramaan chatr sai su samaan |","meaning_en":"three hundred cubits long, four hundred likewise,","page":270,"meaning_status":"draft"},{"gurmukhi":"ਪਾਚ ਸੈ ਖਟ ਸੈ ਲਗੇ ਤਹਿ ਬੀਚ ਆਨ ਗਿਰੰਤ।","roman":"Paach sai khat sai lage tahi beech aan girant |","meaning_en":"five hundred, six hundred, they came and fell into it;","page":270,"meaning_status":"draft"},{"gurmukhi":"ਸਹੰਸ ਹਸਤ ਪ੍ਰਮਾਨ ਲਉ ਸਭ ਹੋਮ ਹੋਤ ਅਨੰਤ। ੪। ੧੬੮।","roman":"Sahans hasat pramaan lau sabh hom hot anant | 4 | 168 |","meaning_en":"up to a thousand cubits long, all were offered, endless.","page":270,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","roman":"Bhujang prayaat chhand","meaning_en":"Bhujang Prayat metre.","page":270,"meaning_status":"draft"},{"type":"verse","number":[1,169],"number_text":"੧। ੧੬੯।","page":270,"lines":[{"gurmukhi":"ਰਚਿਯੋ ਸਰਪ ਮੇਧੰ ਬਡੋ ਜਗ ਰਾਜੰ। ਕਰੈ ਬਿਪ ਹੋਮੈ ਸਰੈ ਸਰਬ ਕਾਜੰ।","roman":"Rachiyo sarap medhan bado jag raajan | karai bip homai sarai sarab kaajan |","meaning_en":"The king arranged the serpent sacrifice, a great sacrifice; the Brahmins made offerings and all the work was accomplished;","page":270,"meaning_status":"draft"},{"gurmukhi":"ਦਹੇ ਸਰਬ ਸਰਪੰ ਅਨੰਤੰ ਪ੍ਰਕਾਰੰ। ਭੁਜੈ ਭੋਗ ਅਨੰਤੰ ਜੁਗੈ ਰਾਜ ਦੁਆਰੰ। ੧। ੧੬੯।","roman":"Dahe sarab sarpan anantan prakaaran | bhujai bhog anantan jugai raaj duaaran | 1 | 169 |","meaning_en":"all serpents of endless kinds were burned; endless food was enjoyed at the king's gate.","page":270,"meaning_status":"draft","note":"ਜੁਗੈ: uncertain; read as 'at'."}]},{"type":"verse","number":[2,170],"number_text":"੨। ੧੭੦।","page":270,"lines":[{"gurmukhi":"ਕਿਤੇ ਅਸਟ ਹਸਤੰ ਸਤੰ ਪ੍ਰਾਇ ਨਾਰੰ। ਕਿਤੇ ਦੁਆਦਿਸੇ ਹਸਤ ਲੌ ਪਰਮ ਭਾਰੰ।","roman":"Kite asat hastan satan praai naaran | kite duaadise hasat lau param bhaaran |","meaning_en":"Some eight cubits long, some nearly a hundred; some twelve cubits long, very heavy;","page":270,"meaning_status":"draft","note":"ਸਤੰ ਪ੍ਰਾਇ ਨਾਰੰ: uncertain; read as 'nearly a hundred'."},{"gurmukhi":"ਕਿਤੇ ਦ੍ਵੈ ਸਹੰਸ੍ਰ ਕਿਤੇ ਜੋਜਨੇਕੰ। ਗਿਰੇ ਹੋਮ ਕੁੰਡੰ ਅਪਾਰੰ ਅਚੇਤੰ। ੨। ੧੭੦।","roman":"Kite dvai sahansr kite jojnekan | gire hom kundan apaaran achetan | 2 | 170 |","meaning_en":"some two thousand, some a yojan long; countless fell senseless into the fire-pit.","page":270,"meaning_status":"draft","note":"ਜੋਜਨ: yojan, a measure of distance (several miles)."}]},{"type":"verse","number":[3,171],"number_text":"੩। ੧੭੧।","page":270,"lines":[{"gurmukhi":"ਕਿਤੇ ਜੋਜਨੇ ਦੁਇ ਕਿਤੇ ਤੀਨ ਜੋਜਨ। ਕਿਤੇ ਚਾਰ ਜੋਜਨ ਦਹੇ ਭੂਮ ਭੋਗਨ।","roman":"Kite jojne dui kite teen jojan | kite chaar jojan dahe bhoom bhogan |","meaning_en":"Some two yojans, some three yojans, some four yojans long, eaters of the earth, were burned;","page":270,"meaning_status":"draft","note":"ਭੂਮ ਭੋਗਨ: read as 'serpents' (that feed on/ lie on the earth); uncertain."},{"gurmukhi":"ਕਿਤੇ ਮੁਸਟ ਅੰਗੁਸਟ ਗ੍ਰਿਸਟੰ ਪ੍ਰਮਾਨੰ। ਕਿਤੇ ਡੇਢੁ ਗਿਸਟੇ ਅੰਗੁਸਟੰ ਅਰਧਾਨੰ। ੩। ੧੭੧।","roman":"Kite musat angusat gristan pramaanan | kite dedhu giste angustan ardhaanan | 3 | 171 |","meaning_en":"some the size of a fist, a thumb or a span; some a span and a half, some half a thumb.","page":270,"meaning_status":"draft","note":"ਗ੍ਰਿਸਟੰ / ਗਿਸਟੇ: read as 'span' (gitth); uncertain."}]},{"type":"verse","number":[4,172],"number_text":"੪। ੧੭੨।","page":270,"lines":[{"gurmukhi":"ਕਿਤੇ ਚਾਰ ਜੋਜਨ ਲਉ ਚਾਰ ਕੋਸੰ। ਛੁਐ ਘ੍ਰਿਤ ਜੈਸੇ ਕਰੈ ਅਗਨ ਹੋਮੰ।","roman":"Kite chaar jojan lau chaar kosan | chhuai ghrit jaise karai agan homan |","meaning_en":"Some four yojans, some four kos long; as ghee is offered and the fire takes it,","page":270,"meaning_status":"draft","note":"ਛੁਐ ਘ੍ਰਿਤ ਜੈਸੇ: uncertain; read as 'as when ghee is poured'."},{"gurmukhi":"ਫਣੰ ਫਟਕੈ ਫੇਣਕਾ ਫੰਤਕਾਰੰ। ਛੁਟੈ ਲਪਟ ਜ੍ਵਾਲਾ ਬਸੈ ਬਿਖਧਾਰੰ। ੪। ੧੭੨।","roman":"Phanan phatkai phenkaa phantkaaran | chhutai lapat jvaalaa basai bikhdhaaran | 4 | 172 |","meaning_en":"their hoods burst, their hoods hissing; tongues of flame shot out, filled with streams of poison.","page":270,"meaning_status":"draft","note":"ਫੇਣਕਾ ਫੰਤਕਾਰੰ: sound-words for hissing; uncertain."}]},{"type":"verse","number":[5,173],"number_text":"੫। ੧੭੩।","page":270,"lines":[{"gurmukhi":"ਕਿਤੇ ਸਪਤ ਜੋਜਨ ਲੌ ਕੋਸ ਅਸਟੰ। ਕਿਤੇ ਅਸਟ ਜੋਜਨ ਮਹਾ ਪਰਮ ਪੁਸਟੰ।","roman":"Kite sapat jojan lau kos astan | kite asat jojan mahaa param pustan |","meaning_en":"Some seven yojans, some eight kos long; some eight yojans, huge and very stout;","page":270,"meaning_status":"draft"},{"gurmukhi":"ਭਯੋ ਘੋਰ ਬਧੰ ਜਰੇ ਕੋਟ ਨਾਗੰ। ਭਜ੍ਯੋ ਤਛਕੰ ਭਛਕੰ ਜੇਮ ਕਾਗੰ। ੫। ੧੭੩।","roman":"Bhayo ghor badhan jare kot naagan | bhajyo tachhkan bhachhkan jem kaagan | 5 | 173 |","meaning_en":"there was a dreadful slaughter; millions of serpents burned; Takshak fled as a crow flees a predator.","page":270,"meaning_status":"draft","note":"ਭਛਕੰ ਜੇਮ ਕਾਗੰ: read as 'like a crow (fleeing)'; uncertain."}]},{"type":"verse","number":[6,174],"number_text":"੬। ੧੭੪।","page":270,"lines":[{"gurmukhi":"ਕੁਲੰ ਕੋਟ ਹੋਮੈ ਬਿਖੈ ਵਹਿਣ ਕੁੰਡੰ। ਬਚੇ ਬਾਧ ਡਾਰੇ ਘਨੇ ਕੁੰਡ ਝੁੰਡੰ।","roman":"Kulan kot homai bikhai vahin kundan | bache baadh daare ghane kund jhundan |","meaning_en":"Millions of serpent clans were offered into the fire-pit; those who survived were bound and thrown in flocks into the pit;","page":270,"meaning_status":"draft"},{"gurmukhi":"ਭਜ੍ਯੋ ਨਾਗ ਰਾਜੰ ਤਕ੍ਯੋ ਇੰਦ੍ਰ ਲੋਕੰ। ਜਰ੍ਯੋ ਬੈਦ ਮੰਤ੍ਰੰ ਭਰ੍ਯੋ ਸਕ੍ਰ ਸੋਕੰ। ੬। ੧੭੪।","roman":"Bhajyo naag raajan takyo indr lokan | jaryo baid mantran bharyo sakr sokan | 6 | 174 |","meaning_en":"the serpent king fled and sought Indra's realm; (the power of) the Vedic mantras burned, and Indra was filled with grief.","page":270,"meaning_status":"draft","note":"ਸਕ੍ਰ: Shakra, Indra."}]},{"type":"verse","number":[7,175],"number_text":"੭। ੧੭੫।","page":271,"lines":[{"gurmukhi":"ਬਧ੍ਯੋ ਮੰਤ੍ਰ ਜੰਤ੍ਰੰ ਗਿਰ੍ਯੋ ਭੂਮ ਮਧੰ। ਅੜਿਓ ਆਸਤੀਕੰ ਮਹਾ ਬਿਪ੍ਰ ਸਿਧੰ।","roman":"Badhyo mantr jantran giryo bhoom madhan | ario aasteekan mahaa bipr sidhan |","meaning_en":"Bound by mantra and yantra, (Takshak) fell to the earth; then Astik, the great accomplished Brahmin, stood firm (against it);","page":271,"meaning_status":"draft"},{"gurmukhi":"ਭਿੜ੍ਯੋ ਭੇੜ ਭੂਪੰ ਝਿਣ੍ਯੋ ਝੇੜ ਝਾੜੰ। ਮਹਾ ਕ੍ਰੋਧ ਉਠ੍ਯੋ ਤਣੀ ਤੋੜ ਤਾੜੰ। ੭। ੧੭੫।","roman":"Bhiryo bher bhoopan jhinyo jher jhaaran | mahaa krodh uthyo tanee tor taaran | 7 | 175 |","meaning_en":"he clashed with the king in fierce dispute; great anger arose, with sharp words.","page":271,"meaning_status":"draft","note":"ਝਿਣ੍ਯੋ ਝੇੜ ਝਾੜੰ, ਤਣੀ ਤੋੜ ਤਾੜੰ: alliterative sound-phrases; sense given loosely; uncertain."}]},{"type":"verse","number":[8,176],"number_text":"੮। ੧੭੬।","page":271,"lines":[{"gurmukhi":"ਤਜ੍ਯੋ ਸ੍ਰਪ ਮੇਧੰ ਭਜ੍ਯੋ ਏਕ ਨਾਥੰ। ਕ੍ਰਿਪਾ ਮੰਤ੍ਰ ਸੂਝੈ ਸਬੈ ਸ੍ਰਿਸਟ ਸਾਜੰ।","roman":"Tajyo srap medhan bhajyo ek naathan | kripaa mantr soojhai sabai srisat saajan |","meaning_en":"\"Give up the serpent sacrifice; worship the one Lord; by His grace the counsel (will) dawn on you that He made all creation.","page":271,"meaning_status":"draft","note":"Speaker (Astik) inferred; ਕ੍ਰਿਪਾ ਮੰਤ੍ਰ ਸੂਝੈ uncertain."},{"gurmukhi":"ਸੁਨਹੁ ਰਾਜ ਸਰਦੂਲ ਬਿਦ੍ਯਾ ਨਿਧਾਨੰ। ਤਪੈ ਤੇਜ ਸਾਵੰਤ ਜੁਆਲਾ ਸਮਾਨੰ। ੮। ੧੭੬।","roman":"Sunhu raaj sardool bidyaa nidhaanan | tapai tej saavant juaalaa samaanan | 8 | 176 |","meaning_en":"Hear, O king, lion among men, treasury of learning, blazing with radiance, mighty, like a flame;","page":271,"meaning_status":"draft","note":"ਸਰਦੂਲ: 'lion/tiger'; ਸਾਵੰਤ: 'warrior/chief'."}]},{"type":"verse","number":[9,177],"number_text":"੯। ੧੭੭।","page":271,"lines":[{"gurmukhi":"ਮਹੀ ਮਾਹ ਰੂਪੰ ਤਪੈ ਤੇਜ ਭਾਨੰ। ਦਸੰ ਚਾਰ ਚਉਦਾਹ ਬਿਦਿਆ ਨਿਧਾਨੰ।","roman":"Mahee maah roopan tapai tej bhaanan | dasan chaar chaudaah bidiaa nidhaanan |","meaning_en":"on the earth your form shines like the sun's radiance; you are the treasury of the fourteen sciences;","page":271,"meaning_status":"draft"},{"gurmukhi":"ਸੁਨਹੁ ਰਾਜ ਸਾਸਤ੍ਰਗ ਸਾਰੰਗ ਪਾਨੰ। ਤਜਹੁ ਸਰਪ ਮੇਧੰ ਦਿਜੈ ਮੋਹਿ ਦਾਨੰ। ੯। ੧੭੭।","roman":"Sunhu raaj saastrag saarang paanan | tajhu sarap medhan dijai mohi daanan | 9 | 177 |","meaning_en":"hear, O king, learned in the shastras, holder of the bow: give up the serpent sacrifice and grant me this gift.","page":271,"meaning_status":"draft"}]},{"type":"verse","number":[10,178],"number_text":"੧੦। ੧੭੮।","page":271,"lines":[{"gurmukhi":"ਤਜਹੁ ਜੋ ਨ ਸਰਪੰ ਜਰੋ ਅਗਨ ਆਪੰ। ਕਰੋ ਦਗਧ ਤੋ ਕੌ ਦਿਵੌ ਐਸ ਸ੍ਰਾਪੰ।","roman":"Tajhu jo na sarpan jaro agan aapan | karo dagadh to kau divau ais sraapan |","meaning_en":"If you do not spare the serpents, I will burn myself in the fire; I will burn you up, I will lay such a curse on you;","page":271,"meaning_status":"draft"},{"gurmukhi":"ਹਣ੍ਯੋ ਪੇਟ ਮਧੰ ਛੁਰੀ ਜਮਦਾੜੰ। ਲਗੇ ਪਾਪ ਤੋਕੋ ਸੁਨਹੁ ਰਾਜ ਗਾੜੰ। ੧੦। ੧੭੮।","roman":"Hanyo pet madhan chhuree jamdaaran | lage paap toko sunhu raaj gaaran | 10 | 178 |","meaning_en":"I will stab a dagger into my belly; the sin will fall on you; hear, O stubborn king.\"","page":271,"meaning_status":"draft","note":"ਜਮਦਾੜੰ: a dagger; ਗਾੜੰ: 'firm/stubborn'; uncertain."}]},{"type":"verse","number":[11,179],"number_text":"੧੧।੧੭੯।","page":271,"lines":[{"gurmukhi":"ਸੁਨੇ ਬਿਪ ਬੋਲੰ ਉਠਿਯੋ ਆਪ ਰਾਜੰ। ਤਜਿਯੋ ਸਰਪ ਮੇਧੰ ਪਿਤਾ ਬੈਰ ਕਾਜੰ।","roman":"Sune bip bolan uthiyo aap raajan | tajiyo sarap medhan pitaa bair kaajan |","meaning_en":"Hearing the Brahmin's words, the king himself rose and gave up the serpent sacrifice made for his father's enmity;","page":271,"meaning_status":"draft"},{"gurmukhi":"ਬੁਲ੍ਯੋ ਬ੍ਯਾਸ ਪਾਸੰ ਕਰਿਯੋ ਮੰਤ੍ਰ ਚਾਰੰ। ਮਹਾ ਬੇਦ ਬਿਆਕਰਣ ਬਿਦਿਆ ਬਿਚਾਰੰ। ੧੧।੧੭੯।","roman":"Bulyo byaas paasan kariyo mantr chaaran | mahaa bed biaakran bidiaa bichaaran | 11 | 179 |","meaning_en":"he called Vyas to him and took good counsel, reflecting on the great Vedas, grammar and learning.","page":271,"meaning_status":"draft"}]},{"type":"verse","number":[12,180],"number_text":"੧੨।੧੮੦।","page":271,"lines":[{"gurmukhi":"ਸੁਨੀ ਪੁਤ੍ਰਕਾ ਦੁਇ ਗ੍ਰਿਹੰ ਕਾਸਿ ਰਾਜੰ। ਮਹਾ ਸੁੰਦਰੀ ਰੂਪ ਸੋਭਾ ਸਮਾਜੰ।","roman":"Sunee putrakaa dui grihan kaasi raajan | mahaa sundree roop sobhaa samaajan |","meaning_en":"He heard of two daughters in the house of the king of Kashi, very beautiful, a gathering of form and grace;","page":271,"meaning_status":"draft"},{"gurmukhi":"ਜਿਣਿਉ ਜਾਇ ਤਾਕੋ ਹਣੋ ਦੁਸਟ ਪੁਸਟੰ। ਕਰਿਯੋ ਧਿਆਨ ਤਾਨੇ ਲਦੇ ਭਾਰ ਉਸਟੰ।੧੨।੧੮੦।","roman":"Jiniu jaai taako hano dusat pustan | kariyo dhiaan taane lade bhaar ustan | 12 | 180 |","meaning_en":"\"I shall go and win them, and slay the wicked and powerful\"; he set his mind on it and loaded the camels.","page":271,"meaning_status":"draft"}]},{"type":"verse","number":[13,181],"number_text":"੧੩।੧੮੧।","page":271,"lines":[{"gurmukhi":"ਚਲੀ ਸੈਨ ਸੂਕਰ ਪਰਾਚੀ ਦਿਸਾਨੰ। ਚੜੇ ਬੀਰ ਧੀਰੰ ਹਠੇ ਸਸਤ੍ਰ ਪਾਨੰ।","roman":"Chalee sain sookar paraachee disaanan | chare beer dheeran hathe sasatr paanan |","meaning_en":"The army marched like boars toward the eastern direction; brave, steady, stubborn heroes rode out, weapons in hand;","page":271,"meaning_status":"draft","note":"ਸੂਕਰ: 'boar'; perhaps describing the army's charge; uncertain."},{"gurmukhi":"ਦੁਰਿਯੋ ਜਾਇ ਦੁਰਗ ਸੁ ਬਾਰਾਣਸੀਸੰ। ਘੇਰਿਯੋ ਜਾਇ ਫਉਜੰ ਭਜਿਓ ਏਕ ਈਸੰ। ੧੩।੧੮੧।","roman":"Duriyo jaai durag su baaraanseesan | gheriyo jaai phaujan bhajio ek eesan | 13 | 181 |","meaning_en":"the lord of Varanasi went and hid in his fort; the army went and besieged it; (the besieged) remembered the one Lord.","page":271,"meaning_status":"draft"}]},{"type":"verse","number":[14,182],"number_text":"੧੪। ੧੮੨।","page":271,"lines":[{"gurmukhi":"ਮਚਿਯੋ ਜੁਧ ਸੁਧੰ ਬਹੇ ਸਸਤ੍ਰ ਘਾਤੰ। ਗਿਰੇ ਅਧੁ ਵਧੰ ਸਨਧੰ ਬਿਪਾਤੰ।","roman":"Machiyo judh sudhan bahe sasatr ghaatan | gire adhu vadhan sandhan bipaatan |","meaning_en":"A pure battle raged; strokes of weapons flowed; men fell cut in half, armoured, in calamity;","page":271,"meaning_status":"draft","note":"ਅਧੁ ਵਧੰ ਸਨਧੰ ਬਿਪਾਤੰ: uncertain."},{"gurmukhi":"ਗਿਰੇ ਹੀਰ ਚੀਰੰ ਸੁ ਬੀਰੰ ਰਜਾਣੰ। ਕਟੈ ਅਧੁ ਅਧੰ ਛੁਟੇ ਰੁਦ੍ਰ ਧ੍ਯਾਨੰ। ੧੪। ੧੮੨।","roman":"Gire heer cheeran su beeran rajaanan | katai adhu adhan chhute rudr dhyaanan | 14 | 182 |","meaning_en":"diamonds and garments fell, fine heroes and princes; cut in halves they fell, and Shiva's meditation was broken.","page":271,"meaning_status":"draft"}]},{"type":"verse","number":[15,183],"number_text":"੧੫। ੧੮੩।","page":272,"lines":[{"gurmukhi":"ਗਿਰੇ ਖੇਤ੍ਰ ਖਤ੍ਰਾਣ ਖਤ੍ਰੀ ਖਤ੍ਰਾਣੰ। ਬਜੀ ਭੇਰ ਭੁੰਕਾਰ ਦ੍ਰੁਕਿਆ ਨਿਸਾਣੰ।","roman":"Gire khetr khatraan khatree khatraanan | bajee bher bhunkaar drukiaa nisaanan |","meaning_en":"Kshatriyas fell on the field, warriors and princes; kettledrums boomed and war-drums sounded;","page":272,"meaning_status":"draft"},{"gurmukhi":"ਕਰੇ ਪੈਜਵਾਰੰ ਪ੍ਰਚਾਰੈ ਸੁ ਬੀਰੰ। ਫਿਰੇ ਰੁੰਡ ਮੁੰਡੰ ਤਣੰ ਤਛ ਤੀਰੰ। ੧੫। ੧੮੩।","roman":"Kare paijvaaran prachaarai su beeran | phire rund mundan tanan tachh teeran | 15 | 183 |","meaning_en":"fine heroes called out challenges and fought on foot; headless trunks moved about, bodies pierced by sharp arrows.","page":272,"meaning_status":"draft","note":"ਪੈਜਵਾਰੰ: read as 'on foot / in vow-bound fighting'; uncertain."}]},{"type":"verse","number":[16,184],"number_text":"੧੬। ੧੮੪।","page":272,"lines":[{"gurmukhi":"ਬਿਭੇ ਦੰਤ ਵਰਮੰ ਪ੍ਰਛੇਦੈ ਤਨਾਨੰ। ਕਰੇ ਮਰਦਨੰ ਅਰਦਨੰ ਮਰਦਮਾਨੰ।","roman":"Bibhe dant varman prachhedai tanaanan | kare maradnan aradnan maradmaanan |","meaning_en":"Tusks pierced armour and tore through bodies; the warriors crushed and trampled one another;","page":272,"meaning_status":"draft","note":"ਮਰਦਮਾਨੰ: 'men/warriors'."},{"gurmukhi":"ਕਟੇ ਚਰਮ ਬਰਮੰ ਛੁਟੇ ਚਉਰ ਚਾਰੰ। ਗਿਰੇ ਬੀਰ ਧੀਰੰ ਛੁਟੇ ਸਸਤ੍ਰ ਧਾਰੰ। ੧੬। ੧੮੪।","roman":"Kate charam barman chhute chaur chaaran | gire beer dheeran chhute sasatr dhaaran | 16 | 184 |","meaning_en":"shields and armour were cut, fine whisks fell away; brave and steady heroes fell, streams of weapons let loose.","page":272,"meaning_status":"draft"}]},{"type":"verse","number":[17,185],"number_text":"੧੭। ੧੮੫।","page":272,"lines":[{"gurmukhi":"ਜਿਣ੍ਯੋ ਕਾਸਕੀਸੰ ਹਣ੍ਯੋ ਸਰਬ ਸੈਨੰ। ਬਰੀ ਪੁਤ੍ਰਕਾ ਤਾਹ ਕੰਪ੍ਯੋ ਤ੍ਰਿਨੈਨੰ।","roman":"Jinyo kaaskeesan hanyo sarab sainan | baree putrakaa taah kanpyo trinainan |","meaning_en":"He conquered the lord of Kashi and slew all his army; he married his daughters, and the three-eyed (Shiva) trembled;","page":272,"meaning_status":"draft"},{"gurmukhi":"ਭਇਓ ਮੇਲ ਗੇਲੰ ਮਿਲੇ ਰਾਜ ਰਾਜੰ। ਭਈ ਮਿਤ੍ਰ ਚਾਰੰ ਸਰੇ ਸਰਬ ਕਾਜੰ। ੧੭। ੧੮੫।","roman":"Bhaio mel gelan mile raaj raajan | bhaee mitr chaaran sare sarab kaajan | 17 | 185 |","meaning_en":"a union was made; king met king; a good friendship came about and all the work was accomplished.","page":272,"meaning_status":"draft"}]},{"type":"verse","number":[18,186],"number_text":"੧੮। ੧੮੬।","page":272,"lines":[{"gurmukhi":"ਮਿਲੀ ਰਾਜ ਦਾਜੰ ਸੁ ਦਾਸੀ ਅਨੂਪੰ। ਮਹਾ ਬਿਦ੍ਯਵੰਤੀ ਅਪਾਰੰ ਸਰੂਪੰ।","roman":"Milee raaj daajan su daasee anoopan | mahaa bidyavantee apaaran saroopan |","meaning_en":"In the royal dowry he received an incomparable maidservant, very learned and of boundless beauty;","page":272,"meaning_status":"draft"},{"gurmukhi":"ਮਿਲੇ ਹੀਰ ਚੀਰੰ ਕਿਤੇ ਸਿਆਉ ਕਰਨੰ। ਮਿਲੇ ਮਤ ਦੰਤੀ ਕਿਤੇ ਸੇਤ ਬਰਨੰ। ੧੮। ੧੮੬।","roman":"Mile heer cheeran kite siaau karnan | mile mat dantee kite set barnan | 18 | 186 |","meaning_en":"he received diamonds and garments, many black-eared (horses), many rutting elephants, many of white colour.","page":272,"meaning_status":"draft"}]},{"type":"verse","number":[19,187],"number_text":"੧੯। ੧੮੭।","page":272,"lines":[{"gurmukhi":"ਕਰਿਯੋ ਬ੍ਯਾਹ ਰਾਜਾ ਭਇਓ ਸੁ ਪ੍ਰਸੰਨੰ। ਭਲੀ ਭਾਤ ਪੋਖੇ ਦਿਜੰ ਸਰਬ ਅੰਨੰ।","roman":"Kariyo byaah raajaa bhaio su prasannan | bhalee bhaat pokhe dijan sarab annan |","meaning_en":"The king was married and greatly pleased; he fed the Brahmins well with every kind of grain;","page":272,"meaning_status":"draft"},{"gurmukhi":"ਕਰੇ ਭਾਤਿ ਭਾਤੰ ਮਹਾ ਗਜ ਦਾਨੰ। ਭਏ ਦੋਇ ਪੁਤ੍ਰੰ ਮਹਾ ਰੂਪ ਮਾਨੰ। ੧੯। ੧੮੭।","roman":"Kare bhaati bhaatan mahaa gaj daanan | bhae doi putran mahaa roop maanan | 19 | 187 |","meaning_en":"he gave great gifts of elephants of many kinds; two sons were born, of great beauty and honour.","page":272,"meaning_status":"draft"}]},{"type":"verse","number":[20,188],"number_text":"੨੦। ੧੮੮।","page":272,"lines":[{"gurmukhi":"ਲਖੀ ਰੂਪਵੰਤੀ ਮਹਾਰਾਜ ਦਾਸੀ। ਮਨੋ ਚੀਰ ਕੈ ਚਾਰ ਚੰਦ੍ਰਾ ਨਿਕਾਸੀ।","roman":"Lakhee roopvantee mahaaraaj daasee | mano cheer kai chaar chandraa nikaasee |","meaning_en":"The great king saw the beautiful maidservant: as if a lovely moon had been drawn out by cutting;","page":272,"meaning_status":"draft","note":"ਚੀਰ ਕੈ ... ਨਿਕਾਸੀ: 'carved out (of the moon)'; uncertain."},{"gurmukhi":"ਲਹੈ ਚੰਚਲਾ ਚਾਰ ਬਿਦਿਆ ਲਤਾ ਸੀ। ਕਿਧੌ ਕੰਜਕੀ ਮਾਝ ਸੋਭਾ ਪ੍ਰਕਾਸੀ। ੨੦। ੧੮੮।","roman":"Lahai chanchlaa chaar bidiaa lataa see | kidhau kanjkee maajh sobhaa prakaasee | 20 | 188 |","meaning_en":"she gleamed like lightning, like a lovely vine of learning, or like a light shining among lotuses;","page":272,"meaning_status":"draft","note":"ਚੰਚਲਾ: 'lightning'; ਕੰਜਕੀ: 'lotuses' or 'maidens'; uncertain."}]},{"type":"verse","number":[21,189],"number_text":"੨੧। ੧੮੯।","page":272,"lines":[{"gurmukhi":"ਕਿਧੌ ਫੂਲ ਮਾਲਾ ਲਖੈ ਚੰਦ੍ਰਮਾ ਸੀ। ਕਿਧੌ ਪਦਮਨੀ ਮੈ ਬਨੀ ਮਾਲਤੀ ਸੀ।","roman":"Kidhau phool maalaa lakhai chandramaa see | kidhau padamnee mai banee maaltee see |","meaning_en":"or she seemed like a garland of flowers, like the moon, or like a malti flower among lotuses,","page":272,"meaning_status":"draft","note":"ਪਦਮਨੀ: 'lotus pond' or a class of woman; uncertain."},{"gurmukhi":"ਕਿਧੌ ਪੁਹਪ ਧੰਨਿਆ ਫੁਲੀ ਰਾਇ ਬੇਲੰ। ਤਜੈ ਅੰਗ ਤੇ ਬਾਸੁ ਚੰਪਾ ਫੁਲੇਲੰ। ੨੧। ੧੮੯।","roman":"Kidhau puhap dhanniaa phulee raai belan | tajai ang te baasu chanpaa phulelan | 21 | 189 |","meaning_en":"or like a blessed flowering vine of Rai Bel; her body gave off the fragrance of champa oil.","page":272,"meaning_status":"draft"}]},{"type":"verse","number":[22,190],"number_text":"੨੨। ੧੯੦।","page":272,"lines":[{"gurmukhi":"ਕਿਧੌ ਦੇਵ ਕੰਨਿਆ ਪ੍ਰਿਥੀ ਲੋਕ ਡੋਲੈ। ਕਿਧੌ ਜਛਨੀ ਕਿਨ੍ਰਨੀ ਸਿਉ ਕਲੋਲੈ।","roman":"Kidhau dev kanniaa prithee lok dolai | kidhau jachhnee kinranee siu kalolai |","meaning_en":"Or a daughter of the gods wandering the earth, or a Yaksha woman sporting with a Kinnar woman,","page":272,"meaning_status":"draft"},{"gurmukhi":"ਕਿਧੌ ਰੁਦ੍ਰ ਬੀਜੰ ਫਿਰੈ ਮਧਿ ਬਾਲੰ। ਕਿਧੌ ਪਤ੍ਰ ਪਾਨੰ ਨਚੈ ਕਉਲ ਨਾਲੰ। ੨੨। ੧੯੦।","roman":"Kidhau rudr beejan phirai madhi baalan | kidhau patr paanan nachai kaul naalan | 22 | 190 |","meaning_en":"or a Rudraksh bead moving among girls, or a betel leaf dancing on a lotus stalk.","page":272,"meaning_status":"draft","note":"ਰੁਦ੍ਰ ਬੀਜੰ: read as Rudraksh seed; uncertain."}]},{"type":"verse","number":[23,191],"number_text":"੨੩। ੧੯੧।","page":273,"lines":[{"gurmukhi":"ਕਿਧੌ ਰਾਗਮਾਲਾ ਰਚੀ ਰੰਗ ਰੂਪੰ। ਕਿਧੌ ਇਸਤ੍ਰਿ ਰਾਜਾ ਰਚੀ ਭੂਪ ਭੂਪੰ।","roman":"Kidhau raagmaalaa rachee rang roopan | kidhau istri raajaa rachee bhoop bhoopan |","meaning_en":"Or a garland of ragas made in colour and form, or a queen fashioned by the King of kings,","page":273,"meaning_status":"draft","note":"ਇਸਤ੍ਰਿ ਰਾਜਾ: 'queen of women'; uncertain."},{"gurmukhi":"ਕਿਧੌ ਨਾਗ ਕੰਨਿਆ ਕਿਧੌ ਬਾਸਵੀ ਹੈ। ਕਿਧੌ ਸੰਖਨੀ ਚਿਤ੍ਰਨੀ ਪਦਮਨੀ ਹੈ। ੨੩। ੧੯੧।","roman":"Kidhau naag kanniaa kidhau baasvee hai | kidhau sankhnee chitranee padamnee hai | 23 | 191 |","meaning_en":"or a serpent's daughter, or a daughter of Vasuki; or a Shankhini, a Chitrini or a Padmini.","page":273,"meaning_status":"draft","note":"Shankhini, Chitrini, Padmini: classes of women in Indian poetics."}]},{"type":"verse","number":[24,192],"number_text":"੨੪।੧੯੨।","page":273,"lines":[{"gurmukhi":"ਲਸੈ ਚਿਤ੍ਰ ਰੂਪੰ ਬਚਿਤ੍ਰੰ ਅਪਾਰੰ। ਮਹਾ ਰੂਪਵੰਤੀ ਮਹਾ ਜੋਬਨਾਰੰ।","roman":"Lasai chitr roopan bachitran apaaran | mahaa roopvantee mahaa jobnaaran |","meaning_en":"Her picture-like form shone, wondrous beyond measure; most beautiful, in the fullness of youth;","page":273,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਗਿਆਨ ਵੰਤੀ ਸੁ ਬਿਗਿਆਨ ਕਰਮੰ। ਪੜੇ ਕੰਠਿ ਬਿਦਿਆ ਸੁ ਬਿਦਿਆਦਿ ਧਰਮੰ।੨੪।੧੯੨।","roman":"Mahaa giaan vantee su bigiaan karman | pare kanthi bidiaa su bidiaadi dharman | 24 | 192 |","meaning_en":"most knowledgeable, skilled in practical learning; she had learning by heart, and the dharma of the sciences.","page":273,"meaning_status":"draft"}]},{"type":"verse","number":[25,193],"number_text":"੨੫। ੧੯੩।","page":273,"lines":[{"gurmukhi":"ਲਖੀ ਰਾਜ ਕੰਨਿਆਨ ਤੇ ਰੂਪਵੰਤੀ। ਲਸੈ ਜੋਤ ਜ੍ਵਾਲਾ ਅਪਾਰੰ ਅਨੰਤੀ।","roman":"Lakhee raaj kanniaan te roopvantee | lasai jot jvaalaa apaaran anantee |","meaning_en":"She was seen as more beautiful than the princesses; her light shone like a flame, boundless and endless;","page":273,"meaning_status":"draft"},{"gurmukhi":"ਲਖ੍ਯੋ ਤਾਹਿ ਜਨਮੇਜਏ ਆਪ ਰਾਜੰ। ਕਰੇ ਪਰਮ ਭੋਗੰ ਦੀਏ ਸਰਬ ਸਾਜੰ। ੨੫। ੧੯੩।","roman":"Lakhyo taahi janmejae aap raajan | kare param bhogan dee'e sarab saajan | 25 | 193 |","meaning_en":"King Janmejai himself saw her; he took his pleasure with her and gave her every kind of finery.","page":273,"meaning_status":"draft"}]},{"type":"verse","number":[26,194],"number_text":"੨੬। ੧੯੪।","page":273,"lines":[{"gurmukhi":"ਬਢਿਓ ਨੇਹੁ ਤਾਸੋ ਤਜੀ ਰਾਜ ਕੰਨਿਆ। ਹੁਤੀ ਸਿਸਟ ਕੀ ਦਿਸਟ ਮਹਿ ਪੁਸਟ ਧੰਨਿਆ।","roman":"Badhio nehu taaso tajee raaj kanniaa | hutee sisat kee disat mahi pusat dhanniaa |","meaning_en":"His love for her grew, and he left the princesses; in the eyes of the world she was the fortunate one.","page":273,"meaning_status":"draft","note":"ਪੁਸਟ ਧੰਨਿਆ: 'well-blessed/fortunate'; uncertain."},{"gurmukhi":"ਭਇਓ ਏਕ ਪੁਤ੍ਰੰ ਮਹਾ ਸਸਤ੍ਰ ਧਾਰੀ। ਦਸੰ ਚਾਰ ਚਉਦਾਹ ਬਿਦਿਆ ਬਿਚਾਰੀ। ੨੬। ੧੯੪।","roman":"Bhaio ek putran mahaa sasatr dhaaree | dasan chaar chaudaah bidiaa bichaaree | 26 | 194 |","meaning_en":"A son was born (to her), a great bearer of weapons, who mastered the fourteen sciences.","page":273,"meaning_status":"draft"}]},{"type":"verse","number":[27,195],"number_text":"੨੭। ੧੯੫।","page":273,"lines":[{"gurmukhi":"ਧਰਿਓ ਅਸਮੇਧੰ ਪ੍ਰਿਥਮ ਪੁਤ੍ਰ ਨਾਮੰ। ਭਇਓ ਅਸਮੇਧਾਨ ਦੂਜੋ ਪ੍ਰਧਾਨੰ।","roman":"Dhario asmedhan pritham putr naaman | bhaio asmedhaan doojo pradhaanan |","meaning_en":"The first son was named Asmedh; the second, Asmedhan, was chief;","page":273,"meaning_status":"draft","note":"These are the queens' two sons; ਅਸਮੇਧ, ਅਸਮੇਧਾਨ transliterated."},{"gurmukhi":"ਅਜੈ ਸਿੰਘ ਰਾਖ੍ਯੋ ਰਜੀ ਪੁਤ੍ਰ ਸੂਰੰ। ਮਹਾ ਜੰਗ ਜੋਧਾ ਮਹਾ ਜਸ ਪੂਰੰ। ੨੭। ੧੯੫।","roman":"Ajai singh raakhyo rajee putr sooran | mahaa jang jodhaa mahaa jas pooran | 27 | 195 |","meaning_en":"the queen's son was named Ajai Singh, a hero, a great warrior in battle, full of great fame.","page":273,"meaning_status":"draft","note":"ਰਜੀ ਪੁਤ੍ਰ: read as 'the son of the maid (rajjo?)'; context suggests the maidservant's son; uncertain."}]},{"type":"verse","number":[28,196],"number_text":"੨੮। ੧੯੬।","page":273,"lines":[{"gurmukhi":"ਭਇਓ ਤਨ ਦੁਰੁਸਤੰ ਬਲਿਸਟੰ ਮਹਾਨੰ। ਮਹਾਜੰਗ ਜੋਧਾ ਸੁ ਸਸਤ੍ਰੰ ਪ੍ਰਧਾਨੰ।","roman":"Bhaio tan durustan balistan mahaanan | mahaajang jodhaa su sastran pradhaanan |","meaning_en":"His body was sound, he was strong and great, a great warrior in battle, foremost with weapons;","page":273,"meaning_status":"draft"},{"gurmukhi":"ਹਣੈ ਦੁਸਟ ਪੁਸਟੰ ਮਹਾ ਸਸਤ੍ਰ ਧਾਰੰ। ਬਡੇ ਸਤ੍ਰ ਜੀਤੇ ਜਿਵੇ ਰਾਵਣਾਰੰ। ੨੮। ੧੯੬।","roman":"Hanai dusat pustan mahaa sasatr dhaaran | bade satr jeete jive raavnaaran | 28 | 196 |","meaning_en":"he slew the wicked and powerful, a great bearer of weapons; he conquered great enemies as Ram (enemy of Ravan) did.","page":273,"meaning_status":"draft","note":"ਰਾਵਣਾਰੰ: 'enemy of Ravan', Ram."}]},{"type":"verse","number":[29,197],"number_text":"੨੯। ੧੯੭।","page":273,"lines":[{"gurmukhi":"ਚੜਿਓ ਏਕ ਦਿਵਸੰ ਅਖੇਟੰ ਨਰੇਸੰ। ਲਖੇ ਮ੍ਰਿਗ ਧਾਯੋ ਗਯੋ ਅਉਰ ਦੇਸੰ।","roman":"Chario ek divsan akhetan naresan | lakhe mrig dhaayo gayo aur desan |","meaning_en":"One day the king rode out hunting; seeing a deer he gave chase and went into another land;","page":273,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰਮਿਓ ਪਰਮ ਬਾਟੰ ਤਕਿਯੋ ਏਕ ਤਾਲੰ। ਤਹਾ ਦਉਰ ਕੈ ਪੀਨ ਪਾਨੰ ਉਤਾਲੰ। ੨੯। ੧੯੭।","roman":"Sramio param baatan takiyo ek taalan | tahaa daur kai peen paanan utaalan | 29 | 197 |","meaning_en":"exhausted on the long road, he spotted a lake; running there, he quickly drank water.","page":273,"meaning_status":"draft"}]},{"type":"verse","number":[30,198],"number_text":"੩੦।੧੯੮।","page":273,"lines":[{"gurmukhi":"ਕਰਿਓ ਰਾਜ ਸੈਨੰ ਕਢਿਓ ਬਾਰ ਬਾਜੰ। ਤਕੀ ਬਾਜਨੀ ਰੂਪ ਰਾਜੰ ਸਮਾਜੰ।","roman":"Kario raaj sainan kadhio baar baajan | takee baajnee roop raajan samaajan |","meaning_en":"The king lay down to rest and took his horse out to the water; a mare there, a queen of beauty, saw it;","page":273,"flags":[{"code":"ੰੰ","reason":"same sign typed twice; written once (prints as one)"}],"meaning_status":"draft","note":"ਬਾਰ: read as 'water' (vari); ਬਾਜਨੀ: 'mare'; uncertain."},{"gurmukhi":"ਲਗ੍ਯੋ ਆਨ ਤਾਕੋ ਰਹ੍ਯੋ ਤਾਹਿ ਗਰਭੰ। ਭਇਓ ਸਿਯਾਮ ਕਰਣੰ ਸੁ ਬਾਜੀ ਅਦਰਬੰ।੩੦।੧੯੮।","roman":"Lagyo aan taako rahyo taahi garbhan | bhaio siyaam karnan su baajee adarban | 30 | 198 |","meaning_en":"she came and mated with it and conceived; a black-eared horse was born, of wondrous kind.","page":273,"meaning_status":"draft","note":"ਅਦਰਬੰ: uncertain; perhaps 'priceless'."}]},{"type":"verse","number":[31,199],"number_text":"੩੧। ੧੯੯।","page":273,"lines":[{"gurmukhi":"ਕਰਿਯੋ ਬਾਜ ਮੇਧੰ ਬਡੋ ਜਗ ਰਾਜਾ। ਜਿਣੇ ਸਰਬ ਭੂਪੰ ਸਰੇ ਸਰਬ ਕਾਜਾ।","roman":"Kariyo baaj medhan bado jag raajaa | jine sarab bhoopan sare sarab kaajaa |","meaning_en":"The king performed a great horse sacrifice; he conquered all the kings and accomplished all his work;","page":273,"meaning_status":"draft"},{"gurmukhi":"ਗਡ੍ਯੋ ਜਗ ਥੰਭੰ ਕਰਿਯੋ ਹੋਮ ਕੁੰਡੰ। ਭਲੀ ਭਾਤ ਪੋਖੇ ਬਲੀ ਬਿਪ੍ਰ ਝੁੰਡੰ। ੩੧। ੧੯੯।","roman":"Gadyo jag thanbhan kariyo hom kundan | bhalee bhaat pokhe balee bipr jhundan | 31 | 199 |","meaning_en":"he set up the sacrificial pillar and made the fire-pit; he fed the mighty crowds of Brahmins well.","page":273,"meaning_status":"draft"}]},{"type":"verse","number":[32,200],"number_text":"੩੨। ੨੦੦।","page":274,"lines":[{"gurmukhi":"ਦਏ ਕੋਟ ਦਾਨੰ ਪਕੇ ਪਰਮ ਪਾਕੰ। ਕਲੂ ਮਧਿ ਕੀਨੋ ਬਡੋ ਧਰਮ ਸਾਕੰ।","roman":"Dae kot daanan pake param paakan | kaloo madhi keeno bado dharam saakan |","meaning_en":"He gave millions in gifts and the finest cooked food; in the Kaliyug he performed a great act of dharma.","page":274,"meaning_status":"draft","note":"ਸਾਕੰ: read as 'deed/feat'; uncertain."},{"gurmukhi":"ਲਗੀ ਦੇਖਨੇ ਆਪ ਜਿਉ ਰਾਜ ਬਾਲਾ। ਮਹਾ ਰੂਪਵੰਤੀ ਮਹਾ ਜੁਆਲ ਆਲਾ। ੩੨। ੨੦੦।","roman":"Lagee dekhne aap jiu raaj baalaa | mahaa roopvantee mahaa juaal aalaa | 32 | 200 |","meaning_en":"The young queen herself came to watch, very beautiful, radiant as a flame.","page":274,"meaning_status":"draft"}]},{"type":"verse","number":[33,201],"number_text":"੩੩। ੨੦੧।","page":274,"lines":[{"gurmukhi":"ਉਡ੍ਯੋ ਪਉਨ ਕੇ ਬੇਗ ਸਿਯੋ ਅਗ੍ਰ ਪਤ੍ਰੰ। ਹਸੇ ਦੇਖ ਨਗਨੰ ਤ੍ਰੀਯੰ ਬਿਪ੍ਰ ਛਤ੍ਰੰ।","roman":"Udyo paun ke beg siyo agr patran | hase dekh nagnan treeyan bipr chhatran |","meaning_en":"By the force of the wind her front garment flew up; seeing the woman naked, the Brahmins and kshatriyas laughed.","page":274,"meaning_status":"draft","note":"ਸਿਯੋ ਅਗ੍ਰ ਪਤ੍ਰੰ: 'her (front) garment'; uncertain."},{"gurmukhi":"ਭਇਓ ਕੋਪ ਰਾਜਾ ਗਹੇ ਬਿਪ੍ਰ ਸਰਬੰ। ਦਹੇ ਖੀਰ ਖੰਡੰ ਬਡੇ ਪਰਮ ਗਰਬੰ। ੩੩। ੨੦੧।","roman":"Bhaio kop raajaa gahe bipr sarban | dahe kheer khandan bade param garban | 33 | 201 |","meaning_en":"The king grew angry and seized all the Brahmins; he burned those very proud men in milk and sugar.","page":274,"meaning_status":"draft"}]},{"type":"verse","number":[34,202],"number_text":"੩੪।੨੦੨।","page":274,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਬਾਧਿ ਕੈ ਸਰਬ ਮੂੰਡੇ ਮੁੰਡਾਏ। ਪੁਨਰ ਏਡੂਆ ਸੀਸ ਤਾਕੇ ਟਿਕਾਏ।","roman":"Pritham baadhi kai sarab moonde mundaae | punar edooaa sees taake tikaae |","meaning_en":"First he bound them all and had their heads shaved; then he set pots on their heads;","page":274,"meaning_status":"draft","note":"ਏਡੂਆ: read as a pot/ring on the head; uncertain."},{"gurmukhi":"ਪੁਨਰ ਤਪਤ ਕੈ ਖੀਰ ਕੇ ਮਧਿ ਡਾਰਿਓ। ਇਮੰ ਸਰਬ ਬਿਪ੍ਰਾਨ ਕਉ ਜਾਰਿ ਮਾਰਿਓ।੩੪।੨੦੨।","roman":"Punar tapat kai kheer ke madhi daario | iman sarab bipraan kau jaari maario | 34 | 202 |","meaning_en":"then he heated the milk and poured it in; thus he burned all the Brahmins to death.","page":274,"meaning_status":"draft"}]},{"type":"verse","number":[35,203],"number_text":"੩੫। ੨੦੩।","page":274,"lines":[{"gurmukhi":"ਕਿਤੇ ਬਾਧਿ ਕੈ ਬਿਪ੍ਰ ਬਾਚੇ ਦਿਵਾਰੰ। ਕਿਤੇ ਬਾਧ ਫਾਸੀ ਦੀਏ ਬਿਪ੍ਰ ਭਾਰੰ।","roman":"Kite baadhi kai bipr baache divaaran | kite baadh phaasee dee'e bipr bhaaran |","meaning_en":"Some Brahmins he bound and walled up in walls; some heavy Brahmins he bound and hanged;","page":274,"meaning_status":"draft","note":"ਬਾਚੇ ਦਿਵਾਰੰ: read as 'bricked into walls'; uncertain."},{"gurmukhi":"ਕਿਤੇ ਬਾਰਿ ਬੋਰੇ ਕਿਤੇ ਅਗਨਿ ਜਾਰੇ। ਕਿਤੇ ਅਧਿ ਚੀਰੇ ਕਿਤੇ ਬਾਧ ਫਾਰੇ। ੩੫। ੨੦੩।","roman":"Kite baari bore kite agni jaare | kite adhi cheere kite baadh phaare | 35 | 203 |","meaning_en":"some he drowned in water, some he burned in fire; some he sawed in half, some he bound and tore apart.","page":274,"meaning_status":"draft"}]},{"type":"verse","number":[36,204],"number_text":"੩੬। ੨੦੪।","page":274,"lines":[{"gurmukhi":"ਲਗਿਯੋ ਦੋਖ ਭੂਪੰ ਬਢਿਯੋ ਕੁਸਟ ਦੇਹੀ। ਸਭੇ ਬਿਪ੍ਰ ਬੋਲੇ ਕਰਿਯੋ ਰਾਜ ਨੇਹੀ।","roman":"Lagiyo dokh bhoopan badhiyo kusat dehee | sabhe bipr bole kariyo raaj nehee |","meaning_en":"Guilt fell on the king, and leprosy spread over his body; all the Brahmins whom the king held dear said:","page":274,"meaning_status":"draft","note":"ਕਰਿਯੋ ਰਾਜ ਨੇਹੀ: read as 'those the king favoured' or 'speaking to the king with affection'; uncertain."},{"gurmukhi":"ਕਹੋ ਕਉਨ ਸੋ ਬੈਠਿ ਕੀਜੈ ਬਿਚਾਰੰ। ਦਹੈ ਦੇਹ ਦੋਖੰ ਮਿਟੈ ਪਾਪ ਭਾਰੰ। ੩੬। ੨੦੪।","roman":"Kaho kaun so baithi keejai bichaaran | dahai deh dokhan mitai paap bhaaran | 36 | 204 |","meaning_en":"\"Tell us, with whom shall we sit and deliberate, so that the body's affliction burns away and the heavy sin is removed?\"","page":274,"meaning_status":"draft"}]},{"type":"verse","number":[37,205],"number_text":"੩੭। ੨੦੫।","page":274,"lines":[{"gurmukhi":"ਬੋਲੇ ਰਾਜ ਦੁਆਰੰ ਸਬੈ ਬਿਪ੍ਰ ਆਏ। ਬਡੇ ਬਿਆਸ ਤੇ ਆਦਿ ਲੈ ਕੇ ਬੁਲਾਏ।","roman":"Bole raaj duaaran sabai bipr aae | bade biaas te aadi lai ke bulaae |","meaning_en":"All the Brahmins who were called came to the king's gate; the great Vyas and others were summoned;","page":274,"meaning_status":"draft"},{"gurmukhi":"ਦੇਖੈ ਲਾਗ ਸਾਸਤ੍ਰੰ ਬੋਲੇ ਬਿਪ੍ਰ ਸਰਬੰ। ਕਰਿਯੋ ਬਿਪ੍ਰਮੇਧੰ ਬਢਿਓ ਭੂਪ ਗਰਬੰ। ੩੭। ੨੦੫।","roman":"Dekhai laag saastran bole bipr sarban | kariyo bipramedhan badhio bhoop garban | 37 | 205 |","meaning_en":"they began to search the shastras, and all the Brahmins said: \"The king's pride grew, and he made a sacrifice of Brahmins.\"","page":274,"meaning_status":"draft"}]},{"type":"verse","number":[38,206],"number_text":"੩੮।੨੦੬।","page":274,"lines":[{"gurmukhi":"ਸੁਨਹੁ ਰਾਜ ਸਰਦੂਲ ਬਿਦਿਆ ਨਿਧਾਨੰ। ਕਰਿਯੋ ਬਿਪ੍ਰ ਮੇਧੰ ਸੁ ਜਗੰ ਪ੍ਰਮਾਨੰ।","roman":"Sunhu raaj sardool bidiaa nidhaanan | kariyo bipr medhan su jagan pramaanan |","meaning_en":"\"Hear, O king, lion among men, treasury of learning: you made a sacrifice of Brahmins, as if it were a proper sacrifice.","page":274,"meaning_status":"draft"},{"gurmukhi":"ਭਇਓ ਅਕਸਮੰਤ੍ਰੰ ਕਹਿਓ ਨਾਹਿ ਕਉਨੈ। ਕਰੀ ਜਉਨ ਹੋਤੀ ਭਈ ਬਾਤ ਤਉਨੈ।੩੮।੨੦੬।","roman":"Bhaio akasmantran kahio naahi kaunai | karee jaun hotee bhaee baat taunai | 38 | 206 |","meaning_en":"It happened suddenly; no one counselled it; what was to happen, that came about.\"","page":274,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft","note":"ਅਕਸਮੰਤ੍ਰੰ: read as 'suddenly (akasmat)' or 'without counsel'; uncertain."}]},{"type":"verse","number":[39,207],"number_text":"੩੯। ੨੦੭।","page":274,"lines":[{"gurmukhi":"ਸੁਨਹੁ ਬਿਆਸ ਤੇ ਪਰਬ ਅਸਟੰ ਦਸਾਨੰ। ਦਹੈ ਦੇਹ ਤੇ ਕੁਸਟ ਸਰਬੰ ਨ੍ਰਿਪਾਨੰ।","roman":"Sunhu biaas te parab astan dasaanan | dahai deh te kusat sarban nripaanan |","meaning_en":"\"Hear the eighteen books (parvas) from Vyas; all the leprosy will burn away from your body, O king.\"","page":274,"meaning_status":"draft"},{"gurmukhi":"ਬੋਲੈ ਬਿਪ੍ਰ ਬਿਆਸੰ ਸੁਨੈ ਲਾਗ ਪਰਬੰ। ਪਰਿਯੋ ਭੂਪ ਪਾਇਨ ਤਜੇ ਸਰਬ ਗਰਬੰ। ੩੯। ੨੦੭।","roman":"Bolai bipr biaasan sunai laag parban | pariyo bhoop paain taje sarab garban | 39 | 207 |","meaning_en":"The Brahmin Vyas spoke and (the king) began to hear the parvas; the king fell at his feet, giving up all pride.","page":274,"meaning_status":"draft"}]},{"type":"verse","number":[40,208],"number_text":"੪੦। ੨੦੮।","page":274,"lines":[{"gurmukhi":"ਸੁਨਹੁ ਰਾਜ ਸਰਦੂਲ ਬਿਦਿਆ ਨਿਧਾਨੰ। ਹੂਓ ਭਰਥ ਕੇ ਬੰਸ ਮੈ ਰਘੁਰਾਨੰ।","roman":"Sunhu raaj sardool bidiaa nidhaanan | hoo'o bharath ke bans mai raghuraanan |","meaning_en":"\"Hear, O king, lion among men, treasury of learning: in the line of Bharat was born Raghu, the king;","page":274,"meaning_status":"draft"},{"gurmukhi":"ਭਇਓ ਤਉਨ ਕੇ ਬੰਸ ਮੈ ਰਾਮ ਰਾਜਾ। ਦੀਜੈ ਛਤ੍ਰ ਦਾਨੰ ਨਿਧਾਨੰ ਬਿਰਾਜਾ। ੪੦। ੨੦੮।","roman":"Bhaio taun ke bans mai raam raajaa | deejai chhatr daanan nidhaanan biraajaa | 40 | 208 |","meaning_en":"in his line was born King Ram, splendid, a treasury of the gift of the royal canopy.","page":274,"meaning_status":"draft","note":"ਦੀਜੈ ਛਤ੍ਰ ਦਾਨੰ ਨਿਧਾਨੰ ਬਿਰਾਜਾ: uncertain."}]},{"type":"verse","number":[41,209],"number_text":"੪੧। ੨੦੯।","page":275,"lines":[{"gurmukhi":"ਭਇਓ ਤਉਨ ਕੀ ਜਦ ਮੈ ਜਦੁ ਰਾਜੰ। ਦਸੰ ਚਾਰ ਚੌਦਹ ਸੁ ਬਿਦਿਆ ਸਮਾਜੰ।","roman":"Bhaio taun kee jad mai jadu raajan | dasan chaar chaudah su bidiaa samaajan |","meaning_en":"In his (family) was born Yadu, king of the Yadavs, endowed with the fourteen sciences;","page":275,"meaning_status":"draft","note":"ਜਦ ਮੈ ਜਦੁ ਰਾਜੰ: uncertain; the genealogy here is as the text gives it."},{"gurmukhi":"ਭਇਓ ਤਉਨ ਕੇ ਬੰਸ ਮੈ ਸੰਤਨੇਅੰ। ਭਏ ਤਾਹਿ ਕੇ ਕਉਰਓ ਪਾਡਵੇਅੰ। ੪੧। ੨੦੯।","roman":"Bhaio taun ke bans mai santnean | bhae taahi ke kaurao paadvean | 41 | 209 |","meaning_en":"in his line was born Shantanu; from him came the Kauravs and the Pandavs.","page":275,"meaning_status":"draft"}]},{"type":"verse","number":[42,210],"number_text":"੪੨। ੨੧੦।","page":275,"lines":[{"gurmukhi":"ਭਏ ਤਉਨ ਕੇ ਬੰਸ ਮੈ ਧ੍ਰਿਤਰਾਸਟਰੰ। ਮਹਾ ਜੁਧ ਜੋਧਾ ਪ੍ਰਬੋਧਾ ਮਹਾ ਸੁਤ੍ਰੰ।","roman":"Bhae taun ke bans mai dhritraasatran | mahaa judh jodhaa prabodhaa mahaa sutran |","meaning_en":"In his line was born Dhritarashtra, great in war, a warrior, wise, with great sons;","page":275,"meaning_status":"draft","note":"ਪ੍ਰਬੋਧਾ ਮਹਾ ਸੁਤ੍ਰੰ: uncertain."},{"gurmukhi":"ਭਏ ਤਉਨ ਕੇ ਕਉਰਵੰ ਕ੍ਰੂਰ ਕਰਮੰ। ਕੀਓ ਛਤ੍ਰਣੰ ਜੈਨ ਕੁਲ ਛੈਣ ਕਰਮੰ। ੪੨। ੨੧੦।","roman":"Bhae taun ke kaurvan kroor karman | keeo chhatranan jain kul chhain karman | 42 | 210 |","meaning_en":"from him came the Kauravs of cruel deeds, who did the deed that destroyed the kshatriya line.","page":275,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft","note":"ਜੈਨ: read as 'who'; uncertain."}]},{"type":"verse","number":[43,211],"number_text":"੪੩। ੨੧੧।","page":275,"lines":[{"gurmukhi":"ਕੀਓ ਭੀਖਮੇ ਅਗ੍ਰ ਸੈਨਾ ਸਮਾਜੰ। ਭਇਓ ਕ੍ਰੁਧ ਜੁਧੰ ਸਮੁਹ ਪੰਡੁ ਰਾਜੰ।","roman":"Keeo bheekhme agr sainaa samaajan | bhaio krudh judhan samuh pandu raajan |","meaning_en":"Bhishma was put at the head of the army; the Pandav king, in anger, came face to face in battle;","page":275,"meaning_status":"draft"},{"gurmukhi":"ਤਹਾ ਗਰਜਿਯੋ ਅਰਜਨੰ ਪਰਮ ਬੀਰੰ। ਧਨੁਰ ਬੇਦ ਗਿਆਤਾ ਤਜੇ ਪਰਮ ਤੀਰੰ। ੪੩। ੨੧੧।","roman":"Tahaa garjiyo arajnan param beeran | dhanur bed giaataa taje param teeran | 43 | 211 |","meaning_en":"there Arjun, the supreme hero, roared; the knower of the science of archery loosed the finest arrows.","page":275,"meaning_status":"draft"}]},{"type":"verse","number":[44,212],"number_text":"੪੪। ੨੧੨।","page":275,"lines":[{"gurmukhi":"ਤਜੀ ਬੀਰ ਬਾਨਾ ਵਰੀ ਬੀਰ ਖੇਤੰ। ਹਣਿਓ ਭੀਖਮੰ ਸਭੈ ਸੈਨਾ ਸਮੇਤੰ।","roman":"Tajee beer baanaa varee beer khetan | hanio bheekhman sabhai sainaa sametan |","meaning_en":"He loosed heroic arrows and won the field of heroes; he struck down Bhishma along with all his army;","page":275,"meaning_status":"draft"},{"gurmukhi":"ਦਈ ਬਾਣਸਿਜਾ ਗਰੇ ਭੀਖਮੈਣੰ। ਜਯੰ ਪਤ੍ਰ ਪਾਇਓ ਸੁਖੰ ਪਾਡਵੇਣੰ। ੪੪। ੨੧੨।","roman":"Daee baansijaa gare bheekhmainan | jayan patr paaio sukhan paadvenan | 44 | 212 |","meaning_en":"he gave Bhishma a bed of arrows; the Pandavs won the letter of victory and found peace.","page":275,"meaning_status":"draft","note":"ਬਾਣਸਿਜਾ ਗਰੇ: 'a bed of arrows (at his neck)'."}]},{"type":"verse","number":[45,213],"number_text":"੪੫। ੨੧੩।","page":275,"lines":[{"gurmukhi":"ਭਏ ਦ੍ਰੋਣ ਸੈਨਾਪਤੀ ਸੈਨਪਾਲੰ। ਭਇਓ ਘੋਰ ਜੁਧੰ ਤਹਾ ਤਉਨ ਕਾਲੰ।","roman":"Bhae dron sainaaptee sainpaalan | bhaio ghor judhan tahaa taun kaalan |","meaning_en":"Drona became commander, protector of the army; a dreadful battle took place there at that time;","page":275,"meaning_status":"draft"},{"gurmukhi":"ਹਣਿਓ ਧ੍ਰਿਸਟ ਦੋਨੰ ਤਜੇ ਦ੍ਰੋਣ ਪ੍ਰਾਣੰ। ਕਰਿਓ ਜੁਧ ਤੇ ਦੇਵਲੋਕੰ ਪਿਆਣੰ। ੪੫। ੨੧੩।","roman":"Hanio dhrisat donan taje dron praanan | kario judh te devlokan piaanan | 45 | 213 |","meaning_en":"Dhrishtadyumn struck him and Drona gave up his life; from the battle he departed to the world of the gods.","page":275,"meaning_status":"draft","note":"Printed ਧ੍ਰਿਸਟ ਦੋਨੰ; read as Dhrishtadyumn."}]},{"type":"verse","number":[46,214],"number_text":"੪੬।੨੧੪।","page":275,"lines":[{"gurmukhi":"ਭਏ ਕਰਣ ਸੈਨਾਪਤੀ ਛਤ੍ਰਪਾਲੰ। ਮਚ੍ਯੋ ਜੁਧ ਕ੍ਰੁਧੰ ਮਹਾ ਬਿਕਰਾਲੰ।","roman":"Bhae karan sainaaptee chhatrapaalan | machyo judh krudhan mahaa bikraalan |","meaning_en":"Karan became commander, protector of kshatriyas; an angry and most dreadful battle raged;","page":275,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft"},{"gurmukhi":"ਹਣਿਓ ਤਾਹਿ ਪੰਥੰ ਸਦੰ ਸੀਸੁ ਕਪਿਓ। ਗਿਰਿਓ ਤਉਣ ਯੁਧਿਸਟਰੰ ਰਾਜੁ ਥਪਿਓ।੪੬।੨੧੪।","roman":"Hanio taahi panthan sadan seesu kapio | girio taun yudhisatran raaju thapio | 46 | 214 |","meaning_en":"Parth (Arjun) slew him and cut off his head; he fell, and Yudhishthir's rule was established.","page":275,"meaning_status":"draft","note":"Printed ਪੰਥੰ; read as Parth (Arjun); ਸਦੰ uncertain."}]},{"type":"verse","number":[47,215],"number_text":"੪੭। ੨੧੫।","page":275,"lines":[{"gurmukhi":"ਭਏ ਸੈਣਪਾਲੰ ਬਲੀ ਸੂਲ ਸਲ੍ਯੰ। ਭਲੀ ਭਾਤਿ ਕੁਟਿਓ ਬਲੀ ਪੰਚ ਦਲ੍ਯੰ।","roman":"Bhae sainpaalan balee sool salyan | bhalee bhaati kutio balee panch dalyan |","meaning_en":"Mighty Shalya with his spear became commander; the mighty one pounded the army of the five well;","page":275,"meaning_status":"draft"},{"gurmukhi":"ਪੁਨਰ ਹਸਤ ਯੁਧਿਸਟਰੰ ਸਕਤ ਬੇਧੰ। ਗਿਰਿਯੋ ਜੁਧ ਭੂਪੰ ਬਲੀ ਭੂਪ ਬੇਧੰ। ੪੭। ੨੧੫।","roman":"Punar hasat yudhisatran sakat bedhan | giriyo judh bhoopan balee bhoop bedhan | 47 | 215 |","meaning_en":"then, pierced by a spear from Yudhishthir's hand, the mighty king fell in battle, pierced by the king.","page":275,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":275,"meaning_status":"draft"},{"type":"verse","number":[1,216],"number_text":"੧। ੨੧੬।","page":275,"lines":[{"gurmukhi":"ਸਲ ਰਾਜਾ ਜਉਨੈ ਦਿਨ ਜੂਝਾ। ਕਉਰਉ ਹਾਰ ਤਵਨ ਤੇ ਸੂਝਾ।","roman":"Sal raajaa jaunai din joojhaa | kaurau haar tavan te soojhaa |","meaning_en":"On the day King Shalya was killed, the Kauravs saw their defeat;","page":275,"meaning_status":"draft"},{"gurmukhi":"ਜੂਝਤ ਸਲ ਭਇਓ ਅਸਤਾਮਾ। ਕੂਟਿਓ ਕੋਟ ਕਟਕੁ ਇਕ ਜਾਮਾ। ੧। ੨੧੬।","roman":"Joojhat sal bhaio astaamaa | kootio kot katku ik jaamaa | 1 | 216 |","meaning_en":"when Shalya was slain, Ashvatthama (took command); in a single watch of the night he crushed millions of the army.","page":275,"meaning_status":"draft","note":"ਅਸਤਾਮਾ: Ashvatthama."}]},{"type":"verse","number":[2,217],"number_text":"੨। ੨੧੭।","page":275,"lines":[{"gurmukhi":"ਧ੍ਰਿਸਟ ਦੋਨੁ ਮਾਰਿਓ ਅਤਿ ਰਥੀ। ਪਾਡਵ ਸੈਨ ਭਲੇ ਕਰਿ ਮਥੀ।","roman":"Dhrisat donu maario ati rathee | paadav sain bhale kari mathee |","meaning_en":"He killed Dhrishtadyumn, the great chariot-warrior, and thoroughly churned the Pandav army;","page":275,"meaning_status":"draft"},{"gurmukhi":"ਪਾਡਵ ਕੇ ਪਾਚੋ ਸੁਤ ਮਾਰੇ। ਦੁਆਪੁਰ ਮੈ ਬਡ ਕੀਨ ਅਖਾਰੇ। ੨। ੨੧੭।","roman":"Paadav ke paacho sut maare | duaapur mai bad keen akhaare | 2 | 217 |","meaning_en":"he killed the five sons of the Pandavs; in the Dvapar age he made a great arena of battle.","page":275,"meaning_status":"draft"}]},{"type":"verse","number":[3,218],"number_text":"੩। ੨੧੮।","page":276,"lines":[{"gurmukhi":"ਕਉਰਉ ਰਾਜ ਕੀਓ ਤਬ ਜੁਧਾ। ਭੀਮ ਸੰਗਿ ਹੁਇ ਕੈ ਅਤਿ ਕ੍ਰੁਧਾ।","roman":"Kaurau raaj keeo tab judhaa | bheem sangi hui kai ati krudhaa |","meaning_en":"Then the Kaurav king fought, with Bhim, in great anger;","page":276,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft"},{"gurmukhi":"ਜੁਧ ਕਰਤ ਕਬਹੂ ਨਹੀ ਹਾਰਾ। ਕਾਲ ਬਲੀ ਤਿਹ ਆਨ ਸੰਘਾਰਾ। ੩। ੨੧੮।","roman":"Judh karat kabhoo nahee haaraa | kaal balee tih aan sanghaaraa | 3 | 218 |","meaning_en":"fighting, he was never defeated; but mighty Death came and destroyed him.","page":276,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","roman":"Bhujang prayaat chhand","meaning_en":"Bhujang Prayat metre.","page":276,"meaning_status":"draft"},{"type":"verse","number":[1,219],"number_text":"੧। ੨੧੯।","page":276,"lines":[{"gurmukhi":"ਤਹਾ ਭੀਮ ਕੁਰਰਾਜ ਸਿਉ ਜੁਧ ਮਚਿਓ। ਛੁਟੀ ਬ੍ਰਹਮ ਤਾਰੀ ਮਹਾ ਰੁਦ੍ਰ ਨਚਿਓ।","roman":"Tahaa bheem kurraaj siu judh machio | chhutee braham taaree mahaa rudr nachio |","meaning_en":"There Bhim fought with the Kuru king; Brahma's trance was broken, and the great Rudra danced;","page":276,"meaning_status":"draft","note":"ਬ੍ਰਹਮ ਤਾਰੀ: 'Brahma's trance/meditation'."},{"gurmukhi":"ਉਠੈ ਸਬਦ ਨਿਰਘਾਤ ਆਘਾਤ ਬੀਰੰ। ਭਏ ਰੁੰਡ ਮੁੰਡੰ ਤਣੰ ਤਛ ਤੀਰੰ। ੧। ੨੧੯।","roman":"Uthai sabad nirghaat aaghaat beeran | bhae rund mundan tanan tachh teeran | 1 | 219 |","meaning_en":"the sound of the heroes' blows and strikes arose; trunks and heads lay about, bodies pierced by sharp arrows.","page":276,"meaning_status":"draft"}]},{"type":"verse","number":[2,220],"number_text":"੨। ੨੨੦।","page":276,"lines":[{"gurmukhi":"ਗਿਰੇ ਬੀਰ ਏਕੰ ਅਨੇਕੰ ਪ੍ਰਕਾਰੰ। ਗਿਰੇ ਅਧ ਅਧੰ ਛੁਧੰ ਸਸਤ੍ਰ ਧਾਰੰ।","roman":"Gire beer ekan anekan prakaaran | gire adh adhan chhudhan sasatr dhaaran |","meaning_en":"Heroes fell, one and many, in many ways; they fell in halves, (struck) by the edges of weapons;","page":276,"meaning_status":"draft","note":"ਛੁਧੰ: uncertain."},{"gurmukhi":"ਕਟੇ ਕਉਰਵੰ ਦੁਰ ਸਿੰਧੂਰ ਖੇਤੰ। ਨਚੇ ਗਿਧ ਆਵਧ ਸਾਵੰਤ ਖੇਤੰ। ੨। ੨੨੦।","roman":"Kate kaurvan dur sindhoor khetan | nache gidh aavadh saavant khetan | 2 | 220 |","meaning_en":"the Kauravs were cut down on the field of battle; vultures danced, and weapons and champions (lay) on the field.","page":276,"meaning_status":"draft","note":"ਦੁਰ ਸਿੰਧੂਰ ਖੇਤੰ: uncertain; perhaps 'vermilion (blood-red) field' or 'elephants'."}]},{"type":"verse","number":[3,221],"number_text":"੩। ੨੨੧।","page":276,"lines":[{"gurmukhi":"ਬਲੀ ਮੰਡਲਾਕਾਰ ਜੂਝੈ ਬਿਰਾਜੈ। ਹਸੈ ਗਰਜ ਠੋਕੈ ਭੁਜਾ ਹਰ ਦੁ ਗਾਜੈ।","roman":"Balee mandlaakaar joojhai biraajai | hasai garaj thokai bhujaa har du gaajai |","meaning_en":"The mighty ones fought splendidly, circling round; they laughed, roared, slapped their arms and thundered;","page":276,"meaning_status":"draft","note":"ਹਰ ਦੁ: uncertain."},{"gurmukhi":"ਦਿਖਾਵੇ ਬਲੀ ਮੰਡਲਾਕਾਰ ਥਾਨੈ। ਉਭਾਰੈ ਭੁਜਾ ਅਉ ਫਟਾਕੈ ਗਜਾਨੈ। ੩। ੨੨੧।","roman":"Dikhaave balee mandlaakaar thaanai | ubhaarai bhujaa au phataakai gajaanai | 3 | 221 |","meaning_en":"the mighty ones showed their circling moves on the spot, raising their arms and swinging their maces.","page":276,"meaning_status":"draft","note":"ਗਜਾਨੈ: 'maces' (gada)."}]},{"type":"verse","number":[4,222],"number_text":"੪। ੨੨੨।","page":276,"lines":[{"gurmukhi":"ਸੁਭੇ ਸਵਰਨ ਕੇ ਪਤ੍ਰ ਬਾਧੇ ਗਜਾ ਮੈ। ਭਈ ਅਗਨਿ ਸੋਭਾ ਲਖੀ ਕੈ ਧੁਜਾ ਮੈ।","roman":"Subhe savran ke patr baadhe gajaa mai | bhaee agni sobhaa lakhee kai dhujaa mai |","meaning_en":"Plates of gold bound on the maces shone; their gleam was like fire seen on a banner;","page":276,"meaning_status":"draft"},{"gurmukhi":"ਭਿੜਾ ਮੈ ਭ੍ਰਮੈ ਮੰਡਲਾਕਾਰ ਬਾਹੈ। ਅਪੋ ਆਪ ਸੈ ਨੇਕਿ ਘਾਇੰ ਸਰਾਹੈ। ੪। ੨੨੨।","roman":"Bhiraa mai bhramai mandlaakaar baahai | apo aap sai neki ghaain saraahai | 4 | 222 |","meaning_en":"in the fight they wheel round in circles and strike, and each praises the other's fine blows.","page":276,"meaning_status":"draft","note":"ਅਪੋ ਆਪ ਸੈ ਨੇਕਿ ਘਾਇੰ ਸਰਾਹੈ: uncertain."}]},{"type":"verse","number":[5,223],"number_text":"੫। ੨੨੩।","page":276,"lines":[{"gurmukhi":"ਤਹਾ ਭੀਮ ਭਾਰੀ ਭੁਜਾ ਸਸਤ੍ਰ ਬਾਹੈ। ਭਲੀ ਭਾਤਿ ਕੈ ਕੈ ਭਲੇ ਸੈਨ ਗਾਹੈ।","roman":"Tahaa bheem bhaaree bhujaa sasatr baahai | bhalee bhaati kai kai bhale sain gaahai |","meaning_en":"There Bhim swings the weapon with his heavy arm and tramples the army thoroughly;","page":276,"meaning_status":"draft"},{"gurmukhi":"ਉਤੈ ਕਉਰਪਾਲੰ ਧਰੈ ਛਤ੍ਰ ਧਰਮੰ। ਕਰੈ ਚਿਤ ਪਾਵਿਤ੍ਰ ਬਾਚਿਤ੍ਰ ਕਰਮੰ। ੫। ੨੨੩।","roman":"Utai kaurpaalan dharai chhatr dharman | karai chit paavitr baachitr karman | 5 | 223 |","meaning_en":"on the other side the Kaurav king holds to kshatriya dharma, doing wondrous deeds with a pure heart.","page":276,"meaning_status":"draft"}]},{"type":"verse","number":[6,224],"number_text":"੬। ੨੨੪।","page":276,"lines":[{"gurmukhi":"ਸਭੈ ਬਾਜੁਵੰਦੰ ਛਕੈ ਭੂਪਨਾਣੰ। ਲਸੈ ਮੁਤਕਾ ਚਾਰ ਦੁਮਲਿਅੰ ਹਾਣੰ।","roman":"Sabhai baajuvandan chhakai bhoopnaanan | lasai mutkaa chaar dumlian haanan |","meaning_en":"All the kings are adorned with armlets; lovely pearls shine on both their necks;","page":276,"meaning_status":"draft","note":"ਦੁਮਲਿਅੰ ਹਾਣੰ: uncertain; perhaps 'two equal (warriors)'."},{"gurmukhi":"ਦੋਊ ਮੀਰ ਧੀਰੰ ਦੋਊ ਪਰਮ ਓਜੰ। ਦੋਊ ਮਾਨਧਾਤਾ ਮਹੀਪੰ ਕਿ ਭੋਜੰ। ੬। ੨੨੪।","roman":"Do'oo meer dheeran do'oo param ojan | do'oo maandhaataa maheepan ki bhojan | 6 | 224 |","meaning_en":"both are steady chiefs, both of supreme vigour; both are kings like Mandhata or Bhoj.","page":276,"meaning_status":"draft","note":"ਮੀਰ: Persian 'chief'."}]},{"type":"verse","number":[7,225],"number_text":"੭। ੨੨੫।","page":276,"lines":[{"gurmukhi":"ਦੋਊ ਬੀਰ ਬਾਨਾ ਬਧੈ ਅਧ ਅਧੰ। ਦੋਊ ਸਸਤ੍ਰ ਧਾਰੀ ਮਹਾ ਜੁਧ ਕ੍ਰੁਧੰ।","roman":"Do'oo beer baanaa badhai adh adhan | do'oo sasatr dhaaree mahaa judh krudhan |","meaning_en":"Both are heroes in warrior dress, slaying (foes) in halves; both bear weapons, in great battle-anger;","page":276,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft"},{"gurmukhi":"ਦੋਊ ਕ੍ਰੂਰ ਕਰਮੰ ਦੋਊ ਜਾਨ ਬਾਹੰ। ਦੋਊ ਹਦਿ ਹਿੰਦੂਨ ਸਾਹਾਨ ਸਾਹੰ। ੭। ੨੨੫।","roman":"Do'oo kroor karman do'oo jaan baahan | do'oo hadi hindoon saahaan saahan | 7 | 225 |","meaning_en":"both are of fierce deeds, both with arms to the knees; both are the bounds of the Hindus, kings of kings.","page":276,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft","note":"ਹਦਿ ਹਿੰਦੂਨ: 'the limit/pride of the Hindus'; uncertain."}]},{"type":"verse","number":[8,226],"number_text":"੮। ੨੨੬।","page":277,"lines":[{"gurmukhi":"ਦੋਊ ਸਸਤ੍ਰ ਧਾਰੰ ਦੋਊ ਪਰਮ ਦਾਨੰ। ਦੋਊ ਢਾਲ ਢੀਚਾਲ ਹਿੰਦੂ ਹਿੰਦਾਨੰ।","roman":"Do'oo sasatr dhaaran do'oo param daanan | do'oo dhaal dheechaal hindoo hindaanan |","meaning_en":"Both bear weapons, both are supreme givers; both are shields and bulwarks of the Hindus;","page":277,"meaning_status":"draft","note":"ਢੀਚਾਲ: uncertain."},{"gurmukhi":"ਦੋਊ ਸਸਤ੍ਰ ਵਰਤੀ ਦੋਊ ਛਤ੍ਰ ਧਾਰੀ। ਦੋਊ ਪਰਮ ਜੋਧਾ ਮਹਾ ਜੁਧਕਾਰੀ। ੮। ੨੨੬।","roman":"Do'oo sasatr vartee do'oo chhatr dhaaree | do'oo param jodhaa mahaa judhkaaree | 8 | 226 |","meaning_en":"both are wielders of weapons, both bear the royal canopy; both are supreme warriors, great fighters.","page":277,"meaning_status":"draft"}]},{"type":"verse","number":[9,227],"number_text":"੯। ੨੨੭।","page":277,"lines":[{"gurmukhi":"ਦੋਊ ਖੰਡ ਖੰਡੀ ਦੋਊ ਮੰਡ ਮੰਡੰ। ਦੋਊ ਜੋਧ ਜੈਤਵਾਰੁ ਜੋਧਾ ਪ੍ਰਚੰਡੰ।","roman":"Do'oo khand khandee do'oo mand mandan | do'oo jodh jaitvaaru jodhaa prachandan |","meaning_en":"Both break (enemies) to pieces, both adorn (the field); both are victorious warriors, fierce fighters;","page":277,"meaning_status":"draft"},{"gurmukhi":"ਦੋਊ ਬੀਰ ਬਾਨੀ ਦੋਊ ਬਾਹ ਸਾਹੰ। ਦੋਊ ਸੂਰ ਸੈਨੰ ਦੋਊ ਸੂਰ ਮਾਹੰ। ੯। ੨੨੭।","roman":"Do'oo beer baanee do'oo baah saahan | do'oo soor sainan do'oo soor maahan | 9 | 227 |","meaning_en":"both are heroes in speech, both are kings in arms; both are heroes of armies, heroes among heroes.","page":277,"meaning_status":"draft","note":"ਬੀਰ ਬਾਨੀ: 'heroic in speech' or 'in heroic dress'; uncertain."}]},{"type":"verse","number":[10,228],"number_text":"੧੦। ੨੨੮।","page":277,"lines":[{"gurmukhi":"ਦੋਊ ਚਕ੍ਰਵਰਤੀ ਦੋਊ ਸਸਤ੍ਰ ਬੇਤਾ। ਦੋਊ ਜੰਗ ਜੋਧੀ ਦੋਊ ਜੰਗ ਜੇਤਾ।","roman":"Do'oo chakravartee do'oo sasatr betaa | do'oo jang jodhee do'oo jang jetaa |","meaning_en":"Both are emperors, both are masters of weapons; both are warriors in war, both are winners of war;","page":277,"meaning_status":"draft"},{"gurmukhi":"ਦੋਊ ਚਿਤ੍ਰ ਜੋਤੀ ਦੋਊ ਚਿਤ੍ਰ ਚਾਪੰ। ਦੋਊ ਚਿਤ੍ਰ ਵਰਮਾ ਦੋਊ ਦੁਸਟ ਤਾਪੰ। ੧੦। ੨੨੮।","roman":"Do'oo chitr jotee do'oo chitr chaapan | do'oo chitr varmaa do'oo dusat taapan | 10 | 228 |","meaning_en":"both shine wondrously, both have wondrous bows; both have wondrous armour, both are scourges of the wicked.","page":277,"meaning_status":"draft"}]},{"type":"verse","number":[11,229],"number_text":"੧੧। ੨੨੯।","page":277,"lines":[{"gurmukhi":"ਦੋਊ ਖੰਡ ਖੰਡੀ ਦੋਊ ਮੰਡ ਮੰਡੰ। ਦੋਊ ਚਿਤ੍ਰ ਜੋਤੀ ਸੁ ਜੋਧਾ ਪ੍ਰਚੰਡੰ।","roman":"Do'oo khand khandee do'oo mand mandan | do'oo chitr jotee su jodhaa prachandan |","meaning_en":"Both break (enemies) to pieces, both adorn (the field); both shine wondrously, fierce warriors;","page":277,"meaning_status":"draft"},{"gurmukhi":"ਦੋਊ ਮਤ ਬਾਰੁੰਨ ਬਿਕ੍ਰਮ ਸਮਾਨੰ। ਦੋਊ ਸਸਤ੍ਰ ਬੇਤਾ ਦੋਊ ਸਸਤ੍ਰ ਪਾਨੰ। ੧੧। ੨੨੯।","roman":"Do'oo mat baarunn bikram samaanan | do'oo sasatr betaa do'oo sasatr paanan | 11 | 229 |","meaning_en":"both are like rutting elephants in valour; both are masters of weapons, both have weapons in hand.","page":277,"meaning_status":"draft","note":"ਬਾਰੁੰਨ: read as 'elephant' (varan)."}]},{"type":"verse","number":[12,230],"number_text":"੧੨। ੨੩੦।","page":277,"lines":[{"gurmukhi":"ਦੋਊ ਪਰਮ ਜੋਧੀ ਦੋਊ ਕ੍ਰੁਧਵਾਨੰ। ਦੋਊ ਸਸਤ੍ਰ ਬੇਤਾ ਦੋਊ ਰੂਪ ਖਾਨੰ।","roman":"Do'oo param jodhee do'oo krudhvaanan | do'oo sasatr betaa do'oo roop khaanan |","meaning_en":"Both are supreme warriors, both are full of wrath; both are masters of weapons, both are mines of beauty;","page":277,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft"},{"gurmukhi":"ਦੋਊ ਛਤ੍ਰਪਾਲੰ ਦੋਊ ਛਤ੍ਰ ਧਰਮੰ। ਦੋਊ ਜੁਧ ਜੋਧਾ ਦੋਊ ਕ੍ਰ�ਰ ਕਰਮੰ। ੧੨। ੨੩੦।","roman":"Do'oo chhatrapaalan do'oo chhatr dharman | do'oo judh jodhaa do'oo kra(?)ra karman | 12 | 230 |","meaning_en":"both are protectors of kshatriyas, both keep kshatriya dharma; both are warriors in battle, both are fierce in deed.","page":277,"flags":[{"code":"0xad","reason":"unresolved: draws an empty box in the PDF itself: the source font lacks this glyph"}],"meaning_status":"draft","note":"A character in ਕ੍ਰ�ਰ is garbled in the printed text; read as ਕ੍ਰੂਰ."}]},{"type":"verse","number":[13,231],"number_text":"੧੩। ੨੩੧।","page":277,"lines":[{"gurmukhi":"ਦੋਊ ਮੰਡਲਾਕਾਰ ਜੂਝੇ ਬਿਰਾਜੈ। ਹਥੈ ਹਰ ਦੁ ਠੋਕੈ ਭੁਜਾ ਪਾਇ ਗਾਜੈ।","roman":"Do'oo mandlaakaar joojhe biraajai | hathai har du thokai bhujaa paai gaajai |","meaning_en":"Both fight splendidly, circling round; they slap their arms with their hands and thunder;","page":277,"meaning_status":"draft","note":"ਹਰ ਦੁ: uncertain."},{"gurmukhi":"ਦੋਊ ਖਤ੍ਰਹਾਣੰ ਦੋਊ ਖਤ੍ਰ ਖੰਡੰ। ਦੋਊ ਖਗ ਪਾਣੰ ਦੋਊ ਛੇਤ੍ਰ ਮੰਡੰ। ੧੩। ੨੩੧।","roman":"Do'oo khatrahaanan do'oo khatr khandan | do'oo khag paanan do'oo chhetr mandan | 13 | 231 |","meaning_en":"both are slayers of kshatriyas, both are breakers of kshatriyas; both have swords in hand, both adorn the field.","page":277,"meaning_status":"draft","note":"ਛੇਤ੍ਰ: read as 'field' (kshetra)."}]},{"type":"verse","number":[14,232],"number_text":"੧੪। ੨੩੨।","page":277,"lines":[{"gurmukhi":"ਦੋਊ ਚਿਤ੍ਰਜੋਤੀ ਦੋਊ ਚਾਰ ਬਿਚਾਰੰ। ਦੋਊ ਮੰਡਲਾਕਾਰ ਖੰਡਾ ਅਬਾਰੰ।","roman":"Do'oo chitrajotee do'oo chaar bichaaran | do'oo mandlaakaar khandaa abaaran |","meaning_en":"Both shine wondrously, both are of good judgement; both wheel round, breaking without check;","page":277,"meaning_status":"draft","note":"ਖੰਡਾ ਅਬਾਰੰ: uncertain."},{"gurmukhi":"ਦੋਊ ਖਗ ਖੂਨੀ ਦੋਊ ਖਤ੍ਰਹਾਣੰ। ਦੋਊ ਖਤ੍ਰਖੇਤਾ ਦੋਊ ਛਤ੍ਰਪਾਣੰ। ੧੪। ੨੩੨।","roman":"Do'oo khag khoonee do'oo khatrahaanan | do'oo khatrakhetaa do'oo chhatrapaanan | 14 | 232 |","meaning_en":"both have bloody swords, both are slayers of kshatriyas; both are kshatriyas on the field, both bear the canopy in hand.","page":277,"meaning_status":"draft"}]},{"type":"verse","number":[15,233],"number_text":"੧੫। ੨੩੩।","page":277,"lines":[{"gurmukhi":"ਦੋਊ ਬੀਰ ਬਿਬ ਆਸਤ ਧਾਰੇ ਨਿਹਾਰੇ। ਰਹੇ ਬ੍ਯੋਮ ਮੈ ਭੂਪ ਗਉਨੈ ਹਕਾਰੇ।","roman":"Do'oo beer bib aasat dhaare nihaare | rahe byom mai bhoop gaunai hakaare |","meaning_en":"Both heroes, bearing (their weapons), were watched by the gods in their aircraft; the kings remained in the sky, calling out;","page":277,"meaning_status":"draft","note":"ਬਿਬ ਆਸਤ: read as 'vimans (aircraft) of the gods'; uncertain."},{"gurmukhi":"ਹਕਾ ਹਕ ਲਾਗੀ ਧਨੰ ਧੰਨ ਜੰਪ੍ਯੋ। ਚਕ੍ਯੋ ਜਛ ਰਾਜੰ ਪ੍ਰਿਥੀ ਲੋਕ ਕੰਪ੍ਯੋ। ੧੫। ੨੩੩।","roman":"Hakaa hak laagee dhanan dhann janpyo | chakyo jachh raajan prithee lok kanpyo | 15 | 233 |","meaning_en":"the clash of challenge rang out, and (all) cried 'Bravo, bravo'; the king of the Yakshas was amazed and the world of the earth trembled.","page":277,"meaning_status":"draft"}]},{"type":"verse","number":[16,234],"number_text":"੧੬। ੨੩੪।","page":277,"lines":[{"gurmukhi":"ਹਨਿਓ ਰਾਜ ਦੁਰਜੋਧਨੰ ਜੁਧ ਭੂਮੰ। ਭਜੇ ਸਭੈ ਜੋਧਾ ਚਲੀ ਧਾਮ ਧੂਮੰ।","roman":"Hanio raaj durjodhnan judh bhooman | bhaje sabhai jodhaa chalee dhaam dhooman |","meaning_en":"King Duryodhan was slain on the battlefield; all the warriors fled; the smoke (of grief) rose in every home;","page":277,"meaning_status":"draft","note":"ਚਲੀ ਧਾਮ ਧੂਮੰ: uncertain; perhaps 'each went home in confusion'."},{"gurmukhi":"ਕਰਿਯੋ ਰਾਜ ਨਿਹਕੰਟਕੰ ਕਉਰਪਾਲੰ। ਪੁਨਰ ਜਾਇ ਕੈ ਮਝਿ ਸਿਝੈ ਹਿਵਾਲੰ। ੧੬। ੨੩੪।","roman":"Kariyo raaj nihkantkan kaurpaalan | punar jaai kai majhi sijhai hivaalan | 16 | 234 |","meaning_en":"the Kuru king (Yudhishthir) ruled without a thorn; then he went and perished in the Himalaya.","page":277,"meaning_status":"draft","note":"ਸਿਝੈ: read as 'was consumed/ended'; uncertain."}]},{"type":"verse","number":[17,235],"number_text":"੧੭। ੨੩੫।","page":278,"lines":[{"gurmukhi":"ਤਹਾ ਏਕ ਗੰਧ੍ਰਬ ਸਿਉ ਜੁਧ ਮਚ੍ਯੋ। ਤਹਾ ਭੂਰਪਾਲੰ ਧੂਰਾ ਰੰਗੁ ਰਚ੍ਯੋ।","roman":"Tahaa ek gandhrab siu judh machyo | tahaa bhoorpaalan dhooraa rangu rachyo |","meaning_en":"There a battle took place with a Gandharva; there the king of the earth made a show of dust (fought fiercely);","page":278,"meaning_status":"draft","note":"ਧੂਰਾ ਰੰਗੁ ਰਚ੍ਯੋ: uncertain."},{"gurmukhi":"ਤਹਾ ਸਤ੍ਰੁ ਕੇ ਭੀਮ ਹਸਤੀ ਚਲਾਏ। ਫਿਰੇ ਮਧਿ ਗੈਣੰ ਅਜਉ ਲਉ ਨ ਆਏ। ੧੭। ੨੩੫।","roman":"Tahaa satru ke bheem hastee chalaae | phire madhi gainan ajau lau na aae | 17 | 235 |","meaning_en":"there Bhim hurled the enemy's elephants; they whirl in the sky and have not come down even yet.","page":278,"meaning_status":"draft","note":"This is the tale Vyas tells, which the king doubts in the next verse."}]},{"type":"verse","number":[18,236],"number_text":"੧੮। ੨੩੬।","page":278,"lines":[{"gurmukhi":"ਸੁਨੈ ਬੈਨ ਕਉ ਭੂਪ ਇਉ ਐਠ ਨਾਕੰ। ਕਰਿਯੋ ਹਾਸ ਮੰਦੈ ਬੁਲ੍ਯੋ ਏਮ ਬਾਕੰ।","roman":"Sunai bain kau bhoop iu aith naakan | kariyo haas mandai bulyo em baakan |","meaning_en":"Hearing these words, the king twisted his nose; he laughed scornfully and spoke thus:","page":278,"meaning_status":"draft"},{"gurmukhi":"ਰਹਿਯੋ ਨਾਕ ਮੈ ਕੁਸਟ ਛਤ੍ਰੀ ਸਵਾਨੰ। ਭਈ ਤਉਨ ਹੀ ਰੋਗ ਤੇ ਭੂਪ ਹਾਨੰ। ੧੮। ੨੩੬।","roman":"Rahiyo naak mai kusat chhatree savaanan | bhaee taun hee rog te bhoop haanan | 18 | 236 |","meaning_en":"the leprosy remained in his nose, O kshatriya lord; and of that very disease the king perished.","page":278,"meaning_status":"draft","note":"ਛਤ੍ਰੀ ਸਵਾਨੰ: read as 'lord of kshatriyas'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":278,"meaning_status":"draft"},{"type":"verse","number":[19,237],"number_text":"੧੯। ੨੩੭।","page":278,"lines":[{"gurmukhi":"ਇਮ ਚਉਰਾਸੀ ਬਰਖ ਪ੍ਰਮਾਨੰ। ਸਪਤ ਮਾਹ ਚਉਬੀਸ ਦਿਨਾਨੰ।","roman":"Im chauraasee barakh pramaanan | sapat maah chaubees dinaanan |","meaning_en":"Thus for eighty-four years, seven months and twenty-four days","page":278,"meaning_status":"draft"},{"gurmukhi":"ਰਾਜ ਕੀਓ ਜਨਮੇਜਾ ਰਾਜਾ। ਕਾਲ ਨੀਸਾਨੁ ਬਹੁਰਿ ਸਿਰਿ ਗਾਜਾ। ੧੯। ੨੩੭।","roman":"Raaj keeo janmejaa raajaa | kaal neesaanu bahuri siri gaajaa | 19 | 237 |","meaning_en":"King Janmejai reigned; then the drum of Death sounded over his head.","page":278,"meaning_status":"draft"}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਜਨਮੇਜਾ ਸਮਾਪਤ ਭਇਆ","roman":"Iti janmejaa samaapat bhaiaa","meaning_en":"Thus ends (the account of) Janmejai.","page":278,"meaning_status":"draft"}],"page":278}});
